(25, 12, 'Lemonade ', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"150\" data-end=\"227\"><p data-start=\"153\" data-end=\"227\">Refreshing drink made with lemon juice, water, and sugar.</p>\r\n</li><p>\r\n</p><li data-start=\"228\" data-end=\"307\">\r\n<p data-start=\"231\" data-end=\"307\"></p></li>', 'en'),
(26, 12, 'عصير الليمون', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>مشروب منعش مصنوع من عصير الليمون والماء والسكر.</p>', 'ar'),
(27, 12, 'Limonada', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Bebida refrescante elaborada con jugo de limón, agua y azúcar.</p>', 'es'),
(28, 13, 'Iced Tea', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"228\" data-end=\"307\"><p data-start=\"231\" data-end=\"307\">Cold tea, often sweetened and flavored with lemon or fruit.</p>\r\n</li><p>\r\n</p><li data-start=\"308\" data-end=\"412\">\r\n<p data-start=\"311\" data-end=\"412\"></p></li>', 'en'),
(29, 13, 'شاي مثلج', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>شاي بارد، غالبًا ما يكون محلى ومنكه بالليمون أو الفاكهة.</p>', 'ar'),
(30, 13, 'té helado', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Té frío, a menudo endulzado y aromatizado con limón o fruta.</p>', 'es'),
(31, 14, 'Milkshake', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"308\" data-end=\"412\"><p data-start=\"311\" data-end=\"412\"> Creamy drink made with milk, ice cream, and flavoring like chocolate or strawberry.</p>\r\n</li><p>\r\n</p><li data-start=\"413\" data-end=\"488\">\r\n<p data-start=\"416\" data-end=\"488\"></p></li>', 'en'),
(32, 14, 'اللبن المخفوق', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>مشروب كريمي مصنوع من الحليب والآيس كريم ونكهة الشوكولاتة أو الفراولة.</p>', 'ar'),
(33, 14, 'Batido', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Bebida cremosa elaborada con leche, helado y saborizante como chocolate o fresa.</p>', 'es'),
(34, 15, 'Smoothie ', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"413\" data-end=\"488\"><p data-start=\"416\" data-end=\"488\"> Thick, blended drink made with fruits, yogurt, or milk.</p>\r\n</li><p>\r\n</p><li data-start=\"489\" data-end=\"566\">\r\n<p data-start=\"492\" data-end=\"566\"></p></li>', 'en'),
(35, 15, 'ملس', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>مشروب سميك مخلوط مصنوع من الفواكه أو الزبادي أو الحليب.</p>', 'ar'),
(36, 15, 'Zalamera', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Bebida espesa y mezclada con frutas, yogur o leche.</p>', 'es'),
(37, 16, 'Cold Coffee', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"489\" data-end=\"566\"><p data-start=\"492\" data-end=\"566\"> Chilled coffee with milk and sugar, often served iced.</p>\r\n</li><p>\r\n</p><li data-start=\"567\" data-end=\"658\">\r\n<p data-start=\"570\" data-end=\"658\"></p></li>', 'en'),
(38, 16, 'القهوة الباردة', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>قهوة مبردة مع الحليب والسكر، وتقدم عادة مثلجة.</p>', 'ar'),
(39, 16, 'Café frío', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Café frío con leche y azúcar, a menudo servido helado.</p>', 'es'),
(40, 17, 'Mojito (Non-Alcoholic) ', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p> Mint, lime, sugar, soda water, and ice for a fresh taste</p>', 'en'),
(41, 17, 'موخيتو (غير كحولي)', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>النعناع والليمون والسكر ومياه الصودا والثلج لنكهة منعشة</p>', 'ar'),
(42, 17, 'Mojito (sin alcohol)', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Menta, lima, azúcar, agua con gas y hielo para un sabor fresco.</p>', 'es'),
(43, 18, 'Orange Juice', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"659\" data-end=\"732\"><p data-start=\"662\" data-end=\"732\">Pure juice from fresh oranges, full of vitamin C.</p>\r\n</li><p>\r\n</p><li data-start=\"733\" data-end=\"839\">\r\n<p data-start=\"736\" data-end=\"839\"></p></li>', 'en'),
(44, 18, 'عصير البرتقال', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>عصير نقي من البرتقال الطازج، غني بفيتامين سي.</p>', 'ar'),
(45, 18, 'Zumo de naranja', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Jugo puro de naranjas frescas, lleno de vitamina C.</p>', 'es'),
(46, 19, 'Green Tea', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Light, slightly bitter tea made from unoxidized tea leaves; often served hot or cold.</p>', 'en'),
(47, 19, 'الشاي الأخضر', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>شاي خفيف، مرير قليلاً، مصنوع من أوراق الشاي غير المؤكسدة؛ يقدم عادةً ساخنًا أو باردًا.</p>', 'ar'),
(48, 19, 'Té verde', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Té ligero y ligeramente amargo elaborado con hojas de té no oxidadas; a menudo servido caliente o frío.</p>', 'es'),
(49, 20, 'Lassi ', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>\r\n<p data-start=\"924\" data-end=\"985\" data-is-last-node=\"\" data-is-only-node=\"\"></p></p><ol data-start=\"73\" data-end=\"922\"><li data-start=\"840\" data-end=\"922\"><p data-start=\"844\" data-end=\"922\">Traditional South Asian yogurt-based drink, can be sweet or salty.</p>\r\n</li>\r\n</ol>', 'en'),
(50, 20, 'لاسي', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>مشروب تقليدي من جنوب آسيا يعتمد على الزبادي، يمكن أن يكون حلوًا أو مالحًا.</p>', 'ar'),
(51, 20, 'Lassi', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>مشروب تقليدي من جنوب آسيا يعتمد على الزبادي، يمكن أن يكون حلوًا أو مالحًا.</p>', 'es'),
(52, 21, 'Margherita Pizza', '{\"variant_name\":\"size\",\"variant_options\":[{\"name\":\"x\",\"price\":\"120\"},{\"name\":\"l\",\"price\":\"180\"}]}', '<p>Classic Italian pizza with tomato sauce, mozzarella, and fresh basil</p>', 'en'),
(53, 21, 'بيتزا مارغريتا', '{\"variant_name\":\"\\u0645\\u0642\\u0627\\u0633\",\"variant_options\":[{\"name\":\"\\u0645\",\"price\":\"120\"},{\"name\":\"\\u0633\",\"price\":\"180\"}]}', '<p>بيتزا إيطالية كلاسيكية مع صلصة الطماطم والموزاريلا والريحان الطازج</p>', 'ar'),
(54, 21, 'Pizza margarita', '{\"variant_name\":\"tama\\u00f1o\",\"variant_options\":[{\"name\":\"x\",\"price\":\"120\"},{\"name\":\"l\",\"price\":\"180\"}]}', '<p>Pizza italiana clásica con salsa de tomate, mozzarella y albahaca fresca.</p>', 'es'),
(55, 22, 'Pepperoni Pizza', '{\"variant_name\":\"size\",\"variant_options\":[{\"name\":\"x\",\"price\":\"x\"},{\"name\":\"l\",\"price\":\"l\"}]}', '<li data-start=\"159\" data-end=\"238\"><p data-start=\"162\" data-end=\"238\">Topped with spicy pepperoni slices and lots of cheese.</p>\r\n</li><p>\r\n</p><li data-start=\"240\" data-end=\"322\">\r\n<p data-start=\"243\" data-end=\"322\"></p></li>', 'en'),
(56, 22, 'بيتزا بيبروني', '{\"variant_name\":\"\\u0645\\u0642\\u0627\\u0633\",\"variant_options\":[{\"name\":\"\\u0645\",\"price\":\"\\u0645\"},{\"name\":\"\\u0633\",\"price\":\"\\u0633\"}]}', '<p>متوّج بشرائح البيبروني الحارة والكثير من الجبن.</p>', 'ar'),
(57, 22, 'Pizza de pepperoni', '{\"variant_name\":\"tama\\u00f1o\",\"variant_options\":[{\"name\":\"x\",\"price\":\"x\"},{\"name\":\"l\",\"price\":\"l\"}]}', '<p>Cubierto con rodajas de pepperoni picante y mucho queso.</p>', 'es'),
(58, 23, 'BBQ Chicken Pizza', '{\"variant_name\":\"size\",\"variant_options\":[{\"name\":\"x\",\"price\":\"x\"},{\"name\":\"l\",\"price\":\"l\"}]}', '<li data-start=\"240\" data-end=\"322\"><p data-start=\"243\" data-end=\"322\">Grilled chicken, BBQ sauce, red onions, and mozzarella.</p></li><li data-start=\"324\" data-end=\"418\"><p data-start=\"327\" data-end=\"418\"></p></li>', 'en'),
(59, 23, 'بيتزا دجاج باربيكيو', '{\"variant_name\":\"\\u0645\\u0642\\u0627\\u0633\",\"variant_options\":[{\"name\":\"\\u0645\",\"price\":\"\\u0645\"},{\"name\":\"\\u0633\",\"price\":\"\\u0633\"}]}', '<p>دجاج مشوي، صلصة باربيكيو، بصل أحمر، وموزاريلا.</p>', 'ar'),
(60, 23, 'Pizza de pollo a la barbacoa', '{\"variant_name\":\"tama\\u00f1o\",\"variant_options\":[{\"name\":\"x\",\"price\":\"x\"},{\"name\":\"l\",\"price\":\"l\"}]}', '<p>Pollo a la parrilla, salsa barbacoa, cebollas rojas y mozzarella.</p>', 'es'),
(61, 24, 'Veggie Pizza', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"324\" data-end=\"418\"><p data-start=\"327\" data-end=\"418\"> Loaded with vegetables like bell peppers, olives, onions, and mushrooms.</p>\r\n</li><p>\r\n</p><li data-start=\"420\" data-end=\"490\">\r\n<p data-start=\"423\" data-end=\"490\"></p></li>', 'en'),
(62, 24, 'بيتزا نباتية', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>محملة بالخضروات مثل الفلفل الحلو والزيتون والبصل والفطر.</p>', 'ar'),
(63, 24, 'Pizza vegetariana', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Cargado con verduras como pimientos morrones, aceitunas, cebollas y champiñones.</p>', 'es'),
(64, 25, 'Hawaiian Pizza', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"420\" data-end=\"490\"><p data-start=\"423\" data-end=\"490\">A sweet and savory combo of ham and pineapple.</p>\r\n</li><p>\r\n</p><li data-start=\"492\" data-end=\"579\">\r\n<p data-start=\"495\" data-end=\"579\"></p></li>', 'en'),
(65, 25, 'بيتزا هاواي', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>مزيج حلو ولذيذ من لحم الخنزير والأناناس.</p>', 'ar'),
(66, 25, 'Pizza hawaiana', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una combinación dulce y salada de jamón y piña.</p>', 'es'),
(67, 26, 'Meat Lovers Pizza', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"492\" data-end=\"579\"><p data-start=\"495\" data-end=\"579\">Packed with sausage, bacon, pepperoni, ham, and ground beef.</p>\r\n</li><p>\r\n</p><li data-start=\"581\" data-end=\"689\">\r\n<p data-start=\"584\" data-end=\"689\"></p></li>', 'en'),
(68, 26, 'بيتزا محبي اللحوم', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تحتوي على النقانق ولحم الخنزير المقدد والبيبروني ولحم الخنزير ولحم البقر المفروم.</p>', 'ar'),
(69, 26, 'Pizza para amantes de la carne', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Repleto de salchicha, tocino, pepperoni, jamón y carne molida.</p>', 'es'),
(70, 27, 'Four Cheese Pizza', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"581\" data-end=\"689\"><p data-start=\"584\" data-end=\"689\"> A cheesy mix of mozzarella, parmesan, gorgonzola, and fontina.</p>\r\n</li><p>\r\n</p><li data-start=\"691\" data-end=\"778\">\r\n<p data-start=\"694\" data-end=\"778\"></p></li>', 'en'),
(71, 27, 'بيتزا الجبن الأربعة', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>مزيج جبن من جبن الموزاريلا والبارميزان والجورجنزولا والفونتينا.</p>', 'ar'),
(72, 27, 'Pizza de cuatro quesos', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una mezcla de quesos: mozzarella, parmesano, gorgonzola y fontina.</p>', 'es'),
(73, 28, 'Buffalo Chicken Pizza ', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"691\" data-end=\"778\"><p data-start=\"694\" data-end=\"778\">Spicy buffalo chicken with blue cheese or ranch drizzle.</p></li><li data-start=\"780\" data-end=\"870\"><p data-start=\"783\" data-end=\"870\"></p></li>', 'en'),
(74, 28, 'بيتزا دجاج بافلو', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>دجاج الجاموس الحار مع الجبن الأزرق أو صلصة الرانش.</p>', 'ar'),
(75, 28, 'Pizza de pollo búfalo', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pollo picante estilo búfalo con queso azul o aderezo ranch.</p>', 'es'),
(76, 29, 'Mushroom Pizza', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"780\" data-end=\"870\"><p data-start=\"783\" data-end=\"870\">Rich mushroom flavor with mozzarella and garlic-infused olive oil.</p>\r\n</li><p>\r\n</p><li data-start=\"872\" data-end=\"981\">\r\n<p data-start=\"876\" data-end=\"981\"></p></li>', 'en'),
(77, 29, 'بيتزا الفطر', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>نكهة الفطر الغنية مع الموزاريلا وزيت الزيتون المنقوع بالثوم.</p>', 'ar'),
(78, 29, 'Pizza de champiñones', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Rico sabor a hongos con mozzarella y aceite de oliva con infusión de ajo.</p>', 'es'),
(79, 30, 'Supreme Pizza ', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"872\" data-end=\"981\"><p data-start=\"876\" data-end=\"981\">A loaded pizza with meats and veggies (like sausage, pepperoni, onions, and peppers).</p>\r\n</li><p>\r\n</p><li data-start=\"983\" data-end=\"1085\">\r\n<p data-start=\"987\" data-end=\"1085\"></p></li>', 'en'),
(80, 30, 'بيتزا سوبريم', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>بيتزا محملة باللحوم والخضروات (مثل السجق والبيبروني والبصل والفلفل).</p>', 'ar'),
(81, 30, 'Pizza suprema', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una pizza cargada de carnes y verduras (como salchichas, pepperoni, cebollas y pimientos).</p>', 'es'),
(82, 31, 'White Pizza', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"983\" data-end=\"1085\"><p data-start=\"987\" data-end=\"1085\"> A pizza without tomato sauce, usually made with ricotta, mozzarella, and garlic.</p>\r\n</li><p>\r\n</p><li data-start=\"1087\" data-end=\"1194\">\r\n<p data-start=\"1091\" data-end=\"1194\"></p></li>', 'en'),
(83, 31, 'بيتزا بيضاء', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>بيتزا بدون صلصة الطماطم، وعادة ما تكون مصنوعة من جبن الريكوتا والموزاريلا والثوم.</p>', 'ar'),
(84, 31, 'Pizza blanca', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una pizza sin salsa de tomate, generalmente hecha con ricotta, mozzarella y ajo.</p>', 'es'),
(85, 32, 'Tandoori Chicken Pizza', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Indian-style pizza with tandoori-spiced chicken, onions, and yogurt sauce.</p>', 'en'),
(86, 32, 'بيتزا دجاج تندوري', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>بيتزا على الطريقة الهندية مع دجاج متبل بالتندوري، وبصل، وصلصة الزبادي.</p>', 'ar'),
(87, 32, 'Pizza de pollo tandoori', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pizza estilo indio con pollo condimentado tandoori, cebollas y salsa de yogur.</p>', 'es'),
(88, 33, 'Seafood Pizza', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"1196\" data-end=\"1274\"><p data-start=\"1200\" data-end=\"1274\">Topped with shrimp, calamari, and sometimes anchovies.</p>\r\n</li><p>\r\n</p><li data-start=\"1276\" data-end=\"1363\">\r\n<p data-start=\"1280\" data-end=\"1363\"></p></li>', 'en'),
(89, 33, 'بيتزا المأكولات البحرية', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تُوّج بالروبيان والحبار وأحيانًا بالأنشوجة.</p>', 'ar'),
(90, 33, 'Pizza de mariscos', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Cubierto con camarones, calamares y, a veces, anchoas.</p>', 'es'),
(91, 34, 'Paneer Tikka Pizza', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"1276\" data-end=\"1363\"><p data-start=\"1280\" data-end=\"1363\">Indian fusion pizza with spiced paneer cubes and capsicum.</p>\r\n</li><p>\r\n</p><li data-start=\"1365\" data-end=\"1478\">\r\n<p data-start=\"1369\" data-end=\"1478\"></p></li>', 'en'),
(92, 34, 'بيتزا بانير تيكا', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>بيتزا هندية مختلطة مع مكعبات بانير متبلة والفلفل الحار.</p>', 'ar'),
(93, 34, 'Pizza de paneer tikka', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pizza de fusión india con cubos de paneer especiados y pimiento.</p>', 'es'),
(94, 35, 'Truffle Mushroom Pizza', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>A gourmet pizza with mushrooms, truffle oil, and cheese for a rich earthy taste.</p>', 'en'),
(95, 35, 'بيتزا فطر الكمأة', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>بيتزا شهية مع الفطر وزيت الكمأة والجبن لإضفاء مذاق ترابي غني.</p>', 'ar'),
(96, 35, 'Pizza de champiñones y trufa', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una pizza gourmet con champiñones, aceite de trufa y queso para un rico sabor terroso.</p>', 'es'),
(97, 36, 'Spaghetti Bolognese', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"63\" data-end=\"181\"><p data-start=\"66\" data-end=\"181\"> Long noodles served with a rich, meaty tomato sauce made from ground beef and herbs.</p>\r\n</li><p>\r\n</p><li data-start=\"183\" data-end=\"288\">\r\n<p data-start=\"186\" data-end=\"288\"></p></li>', 'en'),
(98, 36, 'سباغيتي بولونيز', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>نودلز طويلة تقدم مع صلصة طماطم غنية ولذيذة مصنوعة من لحم البقر المفروم والأعشاب.</p>', 'ar'),
(99, 36, 'Espaguetis a la boloñesa', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Fideos largos servidos con una rica y carnosa salsa de tomate hecha de carne molida y hierbas.</p>', 'es'),
(100, 37, 'Fettuccine Alfredo', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Flat, thick noodles coated in a creamy butter and parmesan cheese sauce.</p>', 'en'),
(101, 37, 'فيتوتشيني ألفريدو', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>نودلز مسطحة وسميكة مغطاة بصلصة كريمة من الزبدة وجبن البارميزان.</p>', 'ar'),
(102, 37, 'Fettuccine Alfredo', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Fideos planos y gruesos cubiertos con una salsa cremosa de mantequilla y queso parmesano.</p>', 'es'),
(103, 38, 'Penne Arrabbiata', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"290\" data-end=\"387\"><p data-start=\"293\" data-end=\"387\"> Short tube-shaped pasta tossed in a spicy tomato and garlic sauce.</p>\r\n</li><p>\r\n</p><li data-start=\"389\" data-end=\"483\">\r\n<p data-start=\"392\" data-end=\"483\"></p></li>', 'en'),
(104, 38, 'أقلام غاضبة', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>معكرونة قصيرة على شكل أنبوب ممزوجة بصلصة الطماطم الحارة والثوم.</p>', 'ar'),
(105, 38, 'Bolígrafos enojados', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pasta corta en forma de tubo bañada en una salsa picante de tomate y ajo.</p>', 'es'),
(106, 39, 'Macaroni and Cheese', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"389\" data-end=\"483\"><p data-start=\"392\" data-end=\"483\"> Elbow-shaped pasta mixed with a creamy, melted cheese sauce.</p>\r\n</li><p>\r\n</p><li data-start=\"485\" data-end=\"599\">\r\n<p data-start=\"488\" data-end=\"599\"></p></li>', 'en'),
(107, 39, 'معكرونة بالجبن', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>معكرونة على شكل مرفق ممزوجة بصلصة الجبن الكريمية المذابة.</p>', 'ar'),
(108, 39, 'Macarrones con queso', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pasta en forma de codo mezclada con una salsa cremosa de queso derretido.</p>', 'es'),
(109, 40, 'Lasagna', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"485\" data-end=\"599\"><p data-start=\"488\" data-end=\"599\">Layered pasta sheets with meat, ricotta cheese, tomato sauce, and topped with melted cheese.</p>\r\n</li><p>\r\n</p><li data-start=\"601\" data-end=\"704\">\r\n<p data-start=\"604\" data-end=\"704\"></p></li>', 'en'),
(110, 40, 'لازانيا', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>شرائح المعكرونة المتعددة الطبقات مع اللحم وجبن الريكوتا وصلصة الطماطم ومغطاة بالجبن المذاب.</p>', 'ar'),
(111, 40, 'Lasaña', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Láminas de pasta en capas con carne, queso ricotta, salsa de tomate y cubiertas con queso derretido.</p>', 'es'),
(112, 41, 'Ravioli', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"601\" data-end=\"704\"><p data-start=\"604\" data-end=\"704\">Stuffed pasta pockets filled with cheese, meat, or vegetables, served with sauce.</p>\r\n</li><p>\r\n</p><li data-start=\"706\" data-end=\"817\">\r\n<p data-start=\"709\" data-end=\"817\"></p></li>', 'en'),
(113, 41, 'رافيول', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>جيوب المعكرونة المحشوة بالجبن أو اللحم أو الخضار، تقدم مع الصلصة.</p>', 'ar'),
(114, 41, 'Ravioles', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Bolsitas de pasta rellenas de queso, carne o verduras, servidas con salsa.</p>', 'es'),
(115, 42, 'Pesto Pasta', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"819\" data-end=\"931\"><p data-start=\"822\" data-end=\"931\">Pasta (often spaghetti or penne) tossed in a green basil, garlic, and olive oil sauce.</p>\r\n</li><p>\r\n</p><li data-start=\"933\" data-end=\"1038\">\r\n<p data-start=\"936\" data-end=\"1038\"></p></li>', 'en'),
(116, 42, 'معكرونة البيستو', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>المعكرونة (عادة ما تكون سباغيتي أو بيني) ممزوجة بصلصة الريحان الأخضر والثوم وزيت الزيتون.</p>', 'ar'),
(117, 42, 'Pasta al pesto', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pasta (a menudo espaguetis o penne) salteadas en una salsa de albahaca verde, ajo y aceite de oliva.</p>', 'es'),
(118, 43, 'Tortellini', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"933\" data-end=\"1038\"><p data-start=\"936\" data-end=\"1038\">Ring-shaped pasta stuffed with cheese or meat, usually served in broth or sauce.</p>\r\n</li><p>\r\n</p><li data-start=\"1040\" data-end=\"1173\">\r\n<p data-start=\"1044\" data-end=\"1173\"></p></li>', 'en'),
(119, 43, 'تورتيليني', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>معكرونة على شكل حلقات محشوة بالجبن أو اللحم، وعادة ما تقدم في المرق أو الصلصة.</p>', 'ar'),
(120, 43, 'Tortellini', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pasta en forma de anillo rellena de queso o carne, generalmente servida en caldo o salsa.</p>', 'es'),
(121, 44, 'Seafood Linguine', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>\r\n<p data-start=\"1175\" data-end=\"1231\" data-is-last-node=\"\" data-is-only-node=\"\"></p></p><ol data-start=\"63\" data-end=\"1173\"><li data-start=\"1040\" data-end=\"1173\"><p data-start=\"1044\" data-end=\"1173\"> Long, flat noodles cooked with shrimp, clams, or other seafood in a light tomato or white wine sauce.</p>\r\n</li>\r\n</ol>', 'en'),
(122, 44, 'لينجويني المأكولات البحرية', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>معكرونة طويلة ومسطحة مطبوخة مع الجمبري أو المحار أو المأكولات البحرية الأخرى في صلصة الطماطم الخفيفة أو صلصة النبيذ الأبيض.</p>', 'ar'),
(123, 44, 'Linguini de mariscos', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Fideos largos y planos cocinados con camarones, almejas u otros mariscos en una salsa ligera de tomate o vino blanco.</p>', 'es'),
(124, 45, 'Caesar Salad', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p data-start=\"70\" data-end=\"88\"><span style=\"font-size: 1rem;\">Made with romaine lettuce, croutons, Parmesan cheese, and Caesar dressing. Often topped with grilled chicken.</span></p>', 'en'),
(125, 45, 'سلطة قيصر', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>مصنوع من خس روماني، خبز محمص، جبن بارميزان، وصلصة سيزر. يُزيّن عادةً بالدجاج المشوي.</p>', 'ar'),
(126, 45, 'Ensalada Cesar', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Elaborada con lechuga romana, crutones, queso parmesano y aderezo César. Suele acompañarse de pollo a la parrilla.</p>', 'es'),
(127, 46, 'Greek Salad', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"205\" data-end=\"340\"><p data-start=\"208\" data-end=\"225\"><span style=\"font-size: 1rem;\">A refreshing mix of cucumber, tomato, red onion, olives, and feta cheese, dressed with olive oil and oregano.</span></p>\r\n</li><p>\r\n</p><li data-start=\"342\" data-end=\"466\">\r\n<p data-start=\"345\" data-end=\"361\"></p></li>', 'en'),
(128, 46, 'سلطة يونانية', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>مزيج منعش من الخيار والطماطم والبصل الأحمر والزيتون وجبن الفيتا، مع زيت الزيتون والزعتر.</p>', 'ar'),
(129, 46, 'Ensalada griega', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una refrescante mezcla de pepino, tomate, cebolla roja, aceitunas y queso feta, aderezada con aceite de oliva y orégano.</p>', 'es'),
(130, 47, 'Cobb Salad', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"342\" data-end=\"466\"><p data-start=\"345\" data-end=\"361\"><span style=\"font-size: 1rem;\">A hearty salad with grilled chicken, bacon, avocado, boiled eggs, tomato, blue cheese, and lettuce.</span></p>\r\n</li><p>\r\n</p><li data-start=\"468\" data-end=\"612\">\r\n<p data-start=\"471\" data-end=\"490\"></p></li>', 'en'),
(131, 47, 'سلطة كوب', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>سلطة شهية مع الدجاج المشوي، لحم الخنزير المقدد، الأفوكادو، البيض المسلوق، الطماطم، الجبن الأزرق، والخس.</p>', 'ar'),
(132, 47, 'Ensalada Cobb', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una ensalada abundante con pollo a la parrilla, tocino, aguacate, huevos duros, tomate, queso azul y lechuga.</p>', 'es'),
(133, 48, 'Caprese Salad', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"468\" data-end=\"612\"><p data-start=\"471\" data-end=\"490\"><span style=\"font-size: 1rem;\">An Italian salad with fresh mozzarella, tomato slices, and basil leaves, drizzled with olive oil and balsamic glaze.</span></p>\r\n</li><p>\r\n</p><li data-start=\"614\" data-end=\"747\">\r\n<p data-start=\"617\" data-end=\"635\"></p></li>', 'en'),
(134, 48, 'سلطة كابريزي', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>سلطة إيطالية مع جبنة موزاريلا طازجة وشرائح طماطم وأوراق ريحان، مع رشة من زيت الزيتون وصلصة بلسميك.</p>', 'ar'),
(135, 48, 'Ensalada Caprese', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una ensalada italiana con mozzarella fresca, rodajas de tomate y hojas de albahaca, rociada con aceite de oliva y glaseado balsámico.</p>', 'es'),
(136, 49, 'Garden Salad', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p data-start=\"617\" data-end=\"635\"><span style=\"font-size: 1rem;\">A simple, fresh mix of lettuce, cucumber, tomato, onion, and carrots, served with your choice of dressing.</span></p>', 'en'),
(137, 49, 'سلطة الحديقة', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>مزيج بسيط وطازج من الخس والخيار والطماطم والبصل والجزر، يقدم مع الصلصة المفضلة لديك.</p>', 'ar'),
(138, 49, 'Ensalada de la huerta', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una mezcla simple y fresca de lechuga, pepino, tomate, cebolla y zanahorias, servida con el aderezo de su elección.</p>', 'es'),
(139, 50, 'Waldorf Salad', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"749\" data-end=\"889\"><p data-start=\"752\" data-end=\"771\"><span style=\"font-size: 1rem;\">Made with apples, celery, grapes, and walnuts in a creamy mayonnaise dressing, often served on a bed of lettuce.</span></p>\r\n</li><p>\r\n</p><li data-start=\"891\" data-end=\"1003\">\r\n<p data-start=\"894\" data-end=\"911\"></p></li>', 'en'),
(140, 50, 'سلطة والدورف', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>يتم تحضيره باستخدام التفاح والكرفس والعنب والجوز في صلصة المايونيز الكريمية، ويتم تقديمه عادة على طبقة من الخس.</p>', 'ar'),
(141, 50, 'Ensalada Waldorf', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Elaborado con manzanas, apio, uvas y nueces en un aderezo de mayonesa cremosa, a menudo servido sobre una cama de lechuga.</p>', 'es'),
(142, 51, 'Pasta Salad', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p data-start=\"894\" data-end=\"911\"><span style=\"font-size: 1rem;\">Cold cooked pasta mixed with vegetables, cheese, and a vinaigrette or creamy dressing.</span></p>', 'en'),
(143, 51, 'سلطة المعكرونة', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>معكرونة مطبوخة باردة ممزوجة بالخضراوات والجبن والصلصة الكريمية.</p>', 'ar'),
(144, 51, 'Ensalada de pasta', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pasta cocida fría mezclada con verduras, queso y una vinagreta o aderezo cremoso.</p>', 'es'),
(145, 52, 'Tuna Salad', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p data-start=\"1008\" data-end=\"1024\"><br></p><p>\r\n</p><ul data-start=\"1028\" data-end=\"1107\">\r\n<li data-start=\"1028\" data-end=\"1107\">\r\n<p data-start=\"1030\" data-end=\"1107\">Tuna mixed with mayo, celery, and onions, served on lettuce or in a sandwich.</p></li></ul>', 'en'),
(146, 52, 'سلطة التونة', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تونة مخلوطة بالمايونيز والكرفس والبصل، تقدم على الخس أو في شطيرة.</p>', 'ar'),
(147, 52, 'Ensalada de atún', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Atún mezclado con mayonesa, apio y cebolla, servido sobre lechuga o en sándwich.</p>', 'es'),
(148, 53, 'Quinoa Salad', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"1109\" data-end=\"1232\"><p data-start=\"1112\" data-end=\"1130\"><span style=\"font-size: 1rem;\">A healthy grain-based salad with quinoa, bell peppers, cucumber, parsley, and lemon vinaigrette.</span></p>\r\n</li><p>\r\n</p><li data-start=\"1234\" data-end=\"1252\">\r\n<p data-start=\"1238\" data-end=\"1252\"></p></li>', 'en'),
(149, 53, 'سلطة الكينوا', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>سلطة صحية تعتمد على الحبوب مع الكينوا والفلفل الحلو والخيار والبقدونس وصلصة الليمون.</p>', 'ar'),
(150, 53, 'Ensalada de quinoa', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una ensalada saludable a base de cereales con quinoa, pimientos morrones, pepino, perejil y vinagreta de limón.</p>', 'es'),
(151, 54, 'Coleslaw', '{\"variant_name\":\"\",\"variant_options\":[]}', '<ol data-start=\"67\" data-end=\"1252\"><li data-start=\"1234\" data-end=\"1252\"><p data-start=\"1238\" data-end=\"1252\"><span style=\"font-size: 1rem;\">Finely shredded cabbage and carrots mixed with creamy or vinegar-based dressing. Often served as a side dish.</span></p></li></ol>', 'en'),
(152, 54, 'سلطة الكرنب', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>كرنب وجزر مفرومان ناعماً، ممزوجان بصلصة كريمية أو خل. يُقدّمان عادةً كطبق جانبي.</p>', 'ar'),
(153, 54, 'Ensalada de col', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Repollo y zanahoria finamente picados, mezclados con aderezo cremoso o a base de vinagre. Suele servirse como guarnición.</p>', 'es'),
(154, 55, 'Chocolate Cake', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"80\" data-end=\"201\"><p data-start=\"83\" data-end=\"201\">A rich, moist cake made with cocoa or melted chocolate, often layered with chocolate frosting.</p>\r\n</li><p>\r\n</p><li data-start=\"203\" data-end=\"314\">\r\n<p data-start=\"206\" data-end=\"314\"></p></li>', 'en'),
(155, 55, 'كعكة الشوكولاتة', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>كعكة غنية ورطبة مصنوعة من الكاكاو أو الشوكولاتة المذابة، وغالبًا ما تكون مغطاة بطبقة من صلصة الشوكولاتة.</p>', 'ar'),
(156, 55, 'Pastel de chocolate', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Un pastel rico y húmedo elaborado con cacao o chocolate derretido, a menudo cubierto con glaseado de chocolate.</p>', 'es'),
(157, 56, 'Ice Cream', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"203\" data-end=\"314\"><p data-start=\"206\" data-end=\"314\">A frozen dairy dessert available in many flavors like vanilla, chocolate, and strawberry.</p>\r\n</li><p>\r\n</p><li data-start=\"316\" data-end=\"446\">\r\n<p data-start=\"319\" data-end=\"446\"></p></li>', 'en'),
(158, 56, 'بوظة', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>حلوى ألبان مجمدة متوفرة بالعديد من النكهات مثل الفانيليا والشوكولاتة والفراولة.</p>', 'ar'),
(159, 56, 'Helado', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Un postre lácteo congelado disponible en muchos sabores como vainilla, chocolate y fresa.</p>', 'es'),
(160, 57, 'Cheesecake', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><br data-start=\"333\" data-end=\"336\">\r\nA creamy dessert made with a base of cream cheese and a buttery biscuit crust, sometimes topped with fruit</p>', 'en'),
(161, 57, 'كعكة الجبن', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>حلوى كريمية مصنوعة من قاعدة من الجبن الكريمي وقشرة بسكويت زبدية، ومغطاة أحيانًا بالفاكهة</p>', 'ar'),
(162, 57, 'Tarta de queso', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Un postre cremoso elaborado con una base de queso crema y una corteza de galleta con mantequilla, a veces cubierto con fruta.</p>', 'es'),
(163, 58, 'Brownies', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"448\" data-end=\"542\"><p data-start=\"451\" data-end=\"542\">Dense, fudgy chocolate squares, often with a crispy top and gooey center.</p>\r\n</li><p>\r\n</p><li data-start=\"544\" data-end=\"649\">\r\n<p data-start=\"547\" data-end=\"649\"></p></li>', 'en'),
(164, 58, 'براونيز', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>مربعات الشوكولاتة الكثيفة والطرية، غالبًا ما تكون ذات قمة مقرمشة ومركز لزج.</p>', 'ar'),
(165, 58, 'Brownies', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Cuadrados de chocolate densos y húmedos, a menudo con una parte superior crujiente y un centro pegajoso.</p>', 'es'),
(166, 59, 'Donuts', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"544\" data-end=\"649\"><p data-start=\"547\" data-end=\"649\">Deep-fried sweet dough rings or balls, glazed or filled with cream, jam, or chocolate.</p>\r\n</li><p>\r\n</p><li data-start=\"651\" data-end=\"750\">\r\n<p data-start=\"654\" data-end=\"750\"></p></li>', 'en'),
(167, 59, 'دوناتس', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>حلقات أو كرات من العجين الحلو المقلي، مغطاة أو محشوة بالكريمة أو المربى أو الشوكولاتة.</p>', 'ar'),
(168, 59, 'Donas', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Anillos o bolas de masa dulce fritas, glaseadas o rellenas de crema, mermelada o chocolate.</p>', 'es'),
(169, 60, 'Cupcakes', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"651\" data-end=\"750\"><p data-start=\"654\" data-end=\"750\">Mini cakes baked in paper cups, topped with frosting and decorative sprinkles.</p>\r\n</li><p>\r\n</p><li data-start=\"752\" data-end=\"845\">\r\n<p data-start=\"755\" data-end=\"845\"></p></li>', 'en'),
(170, 60, 'كب كيك', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>كعكات صغيرة مخبوزة في أكواب ورقية، ومغطاة بالكريمة والرشات الزخرفية.</p>', 'ar'),
(171, 60, 'Magdalenas', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Mini pasteles horneados en vasos de papel, cubiertos con glaseado y chispas decorativas.</p>', 'es'),
(172, 61, 'Macarons', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"752\" data-end=\"845\"><p data-start=\"755\" data-end=\"845\"><br data-start=\"767\" data-end=\"770\">\r\nFrench almond meringue cookies filled with ganache, buttercream, or jam.</p>\r\n</li><p>\r\n</p><li data-start=\"847\" data-end=\"973\">\r\n<p data-start=\"850\" data-end=\"973\"></p></li>', 'en'),
(173, 61, 'الماكرون', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>كوكيز اللوز الفرنسي المحشو بالغاناش أو الكريمة أو المربى.</p>', 'ar'),
(174, 61, 'Macarrones', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Galletas francesas de merengue de almendras rellenas de ganache, crema de mantequilla o mermelada.</p>', 'es'),
(175, 62, 'Pudding', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"847\" data-end=\"973\"><p data-start=\"850\" data-end=\"973\">A soft, creamy dessert made from milk, sugar, and cornstarch or eggs (e.g., chocolate or vanilla pudding).</p>\r\n</li><p>\r\n</p><li data-start=\"975\" data-end=\"1081\">\r\n<p data-start=\"978\" data-end=\"1081\"></p></li>', 'en'),
(176, 62, 'بودنغ', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>حلوى ناعمة وكريمية مصنوعة من الحليب والسكر والنشا أو البيض (مثل بودنغ الشوكولاتة أو الفانيليا).</p>', 'ar'),
(177, 62, 'Pudín', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Un postre suave y cremoso elaborado con leche, azúcar y maicena o huevos (por ejemplo, pudín de chocolate o vainilla).</p>', 'es'),
(178, 63, 'Fruit Tart', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"975\" data-end=\"1081\"><p data-start=\"978\" data-end=\"1081\">A pastry crust filled with custard or cream and topped with fresh, colorful fruits.</p>\r\n</li><p>\r\n</p><li data-start=\"1083\" data-end=\"1203\">\r\n<p data-start=\"1087\" data-end=\"1203\"></p></li>', 'en'),
(179, 63, 'فطيرة الفاكهة', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>عجينة معجنات محشوة بالكاسترد أو الكريمة ومغطاة بالفواكه الطازجة الملونة.</p>', 'ar'),
(180, 63, 'Tarta de frutas', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una masa de hojaldre rellena de crema pastelera o crema y cubierta con frutas frescas y coloridas.</p>', 'es'),
(181, 64, 'Gulab Jamun', '{\"variant_name\":\"\",\"variant_options\":[]}', '<ol data-start=\"80\" data-end=\"1203\"><li data-start=\"1083\" data-end=\"1203\"><p data-start=\"1087\" data-end=\"1203\">A traditional South Asian dessert made from milk solids, deep-fried, and soaked in sugar syrup.</p>\r\n</li>\r\n</ol>', 'en'),
(182, 64, 'طبق حلو', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>حلوى جنوب آسيوية تقليدية مصنوعة من المواد الصلبة في الحليب، مقلية، ومنقوعة في شراب السكر.</p>', 'ar'),
(183, 64, 'plato dulce', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Un postre tradicional del sur de Asia elaborado con sólidos lácteos, fritos y remojados en almíbar de azúcar.</p>', 'es'),
(184, 65, 'Chicken Noodle Soup', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"69\" data-end=\"208\"><p data-start=\"72\" data-end=\"208\">A comforting soup made with shredded chicken, egg noodles, carrots, and celery in a clear, flavorful broth.</p>\r\n</li><p>\r\n</p><li data-start=\"210\" data-end=\"318\">\r\n<p data-start=\"213\" data-end=\"318\"></p></li>', 'en'),
(185, 65, 'شوربة الدجاج بالنودلز', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>حساء مريح مصنوع من الدجاج المبشور، ومعكرونة البيض، والجزر، والكرفس في مرق شفاف ولذيذ.</p>', 'ar'),
(186, 65, 'Sopa de pollo con fideos', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una sopa reconfortante hecha con pollo desmenuzado, fideos de huevo, zanahorias y apio en un caldo claro y sabroso.</p>', 'es'),
(187, 66, 'Tomato Soup', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><br data-start=\"228\" data-end=\"231\">\r\nA smooth, tangy soup made from pureed tomatoes, often served with cream or croutons</p>', 'en'),
(188, 66, 'حساء الطماطم', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>حساء ناعم وحامض مصنوع من الطماطم المهروسة، ويقدم غالبًا مع الكريمة أو الخبز المحمص</p>', 'ar'),
(189, 66, 'Sopa de tomate', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una sopa suave y picante hecha con puré de tomates, a menudo servida con crema o crutones.</p>', 'es'),
(190, 67, 'Mushroom Soup', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"320\" data-end=\"439\"><p data-start=\"323\" data-end=\"439\">Creamy or clear soup made with fresh mushrooms, herbs, and garlic; rich and earthy in flavor.</p>\r\n</li><p>\r\n</p><li data-start=\"441\" data-end=\"567\">\r\n<p data-start=\"444\" data-end=\"567\"></p></li>', 'en'),
(191, 67, 'حساء الفطر', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>حساء كريمي أو شفاف مصنوع من الفطر الطازج والأعشاب والثوم؛ غني بالنكهة الترابية.</p>', 'ar'),
(192, 67, 'Sopa de hongos', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Sopa cremosa o clara hecha con hongos frescos, hierbas y ajo; de sabor rico y terroso.</p>', 'es'),
(193, 68, 'Sweet Corn Soup', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"441\" data-end=\"567\"><p data-start=\"444\" data-end=\"567\">A light and slightly sweet Indo-Chinese soup made with corn, vegetables, and a touch of soy sauce.</p>\r\n</li><p>\r\n</p><li data-start=\"569\" data-end=\"690\">\r\n<p data-start=\"572\" data-end=\"690\"></p></li>', 'en'),
(194, 68, 'شوربة الذرة الحلوة', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>حساء هندي صيني خفيف وحلو قليلاً، مصنوع من الذرة والخضروات مع لمسة من صلصة الصويا.</p>', 'ar'),
(195, 68, 'Sopa de maíz dulce', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una sopa indochina ligera y ligeramente dulce hecha con maíz, verduras y un toque de salsa de soja.</p>', 'es'),
(196, 69, 'Lentil Soup (Daal Soup)', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"569\" data-end=\"690\"><p data-start=\"572\" data-end=\"690\"><span style=\"font-size: 1rem;\">A healthy, protein-rich soup made with lentils, spices, and often tomatoes or garlic.</span></p>\r\n</li><p>\r\n</p><li data-start=\"692\" data-end=\"799\">\r\n<p data-start=\"695\" data-end=\"799\"></p></li>', 'en'),
(197, 69, 'شوربة العدس', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>حساء صحي غني بالبروتين مصنوع من العدس والتوابل والطماطم أو الثوم في كثير من الأحيان.</p>', 'ar'),
(198, 69, 'Sopa de lentejas', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una sopa saludable y rica en proteínas hecha con lentejas, especias y, a menudo, tomates o ajo.</p>', 'es'),
(199, 70, 'Hot and Sour Soup', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"692\" data-end=\"799\"><p data-start=\"695\" data-end=\"799\"><br data-start=\"716\" data-end=\"719\">\r\nA Chinese-style spicy and tangy soup made with tofu, vegetables, and vinegar.</p>\r\n</li><p>\r\n</p><li data-start=\"801\" data-end=\"912\">\r\n<p data-start=\"804\" data-end=\"912\"></p></li>', 'en'),
(200, 70, 'حساء حار وحامض', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>حساء حار ولذيذ على الطريقة الصينية مصنوع من التوفو والخضروات والخل.</p>', 'ar'),
(201, 70, 'Sopa agridulce', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una sopa picante y agria al estilo chino hecha con tofu, verduras y vinagre.</p>', 'es'),
(202, 71, 'Pumpkin Soup', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"801\" data-end=\"912\"><p data-start=\"804\" data-end=\"912\">A creamy soup made from pureed pumpkin, flavored with spices like nutmeg and cinnamon.</p>\r\n</li><p>\r\n</p><li data-start=\"914\" data-end=\"1033\">\r\n<p data-start=\"917\" data-end=\"1033\"></p></li>', 'en'),
(203, 71, 'حساء اليقطين', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>حساء كريمي مصنوع من اليقطين المهروس، بنكهة التوابل مثل جوزة الطيب والقرفة.</p>', 'ar'),
(204, 71, 'Sopa de calabaza', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una sopa cremosa hecha con puré de calabaza, aromatizada con especias como nuez moscada y canela.</p>', 'es'),
(205, 72, 'Nashville Hot Chicken', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"77\" data-end=\"207\"><p data-start=\"80\" data-end=\"207\">Spicy, deep-fried chicken coated in a cayenne pepper paste, served with pickles and white bread.</p>\r\n</li><p>\r\n</p><li data-start=\"209\" data-end=\"342\">\r\n<p data-start=\"212\" data-end=\"342\"></p></li>', 'en'),
(206, 72, 'دجاج ناشفيل الحار', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>دجاج مقلي حار مغطى بمعجون الفلفل الحار، يقدم مع المخللات والخبز الأبيض.</p>', 'ar'),
(207, 72, 'Pollo picante de Nashville', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pollo picante frito cubierto con una pasta de pimienta cayena, servido con pepinillos y pan blanco.</p>', 'es'),
(208, 73, 'Buffalo Chicken Wings', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"209\" data-end=\"342\"><p data-start=\"212\" data-end=\"342\">Chicken wings tossed in tangy buffalo sauce, usually served with blue cheese dip and celery sticks.</p>\r\n</li><p>\r\n</p><li data-start=\"344\" data-end=\"481\">\r\n<p data-start=\"347\" data-end=\"481\"></p></li>', 'en'),
(209, 73, 'أجنحة دجاج بافلو', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>أجنحة دجاج متبلة بصلصة الجاموس اللذيذة، تقدم عادة مع صلصة الجبن الأزرق وأعواد الكرفس.</p>', 'ar'),
(210, 73, 'Alitas de pollo estilo búfalo', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Alitas de pollo bañadas en salsa picante de búfalo, generalmente servidas con salsa de queso azul y palitos de apio.</p>', 'es'),
(211, 74, 'Spicy Chicken Curry', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"344\" data-end=\"481\"><p data-start=\"347\" data-end=\"481\">Tender chicken simmered in a rich, spicy gravy with Indian spices like chili, turmeric, and garam masala.</p>\r\n</li><p>\r\n</p><li data-start=\"483\" data-end=\"588\">\r\n<p data-start=\"486\" data-end=\"588\"></p></li>', 'en'),
(212, 74, 'كاري الدجاج الحار', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>دجاج طري مطهو في مرق غني وحار مع توابل هندية مثل الفلفل الحار والكركم والماسالا الحارة.</p>', 'ar'),
(213, 74, 'Pollo al curry picante', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pollo tierno cocinado a fuego lento en una salsa rica y picante con especias indias como chile, cúrcuma y garam masala.</p>', 'es'),
(214, 75, 'Hot Honey Fried Chicken', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"483\" data-end=\"588\"><p data-start=\"486\" data-end=\"588\"> Crispy fried chicken glazed with a sweet and spicy honey-chili sauce.</p></li><li data-start=\"590\" data-end=\"713\"><p data-start=\"593\" data-end=\"713\"></p></li>', 'en'),
(215, 75, 'دجاج مقلي بالعسل الحار', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>دجاج مقلي مقرمش مغطى بصلصة العسل والفلفل الحلو والحار.</p>', 'ar'),
(216, 75, 'Pollo frito con miel picante', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pollo frito crujiente glaseado con una salsa picante y dulce de miel y chile.</p>', 'es'),
(217, 76, 'Spicy Korean Chicken (Yangnyeom)', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"590\" data-end=\"713\"><p data-start=\"593\" data-end=\"713\"> Double-fried chicken tossed in a sticky, sweet, and spicy Korean chili sauce.</p>\r\n</li><p>\r\n</p><li data-start=\"715\" data-end=\"836\">\r\n<p data-start=\"718\" data-end=\"836\"></p></li>', 'en'),
(218, 76, 'دجاج كوري حار', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>دجاج مقلي مرتين في صلصة الفلفل الحار الكورية اللزجة والحلوة والحارة.</p>', 'ar'),
(219, 76, 'Pollo picante coreano', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pollo frito dos veces bañado en una salsa de chile coreana pegajosa, dulce y picante.</p>', 'es'),
(220, 77, 'Jerk Chicken', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"715\" data-end=\"836\"><p data-start=\"718\" data-end=\"836\"><br data-start=\"734\" data-end=\"737\"> Grilled chicken marinated in a hot and smoky Jamaican jerk spice mix with Scotch bonnet peppers.</p>\r\n</li><p>\r\n</p><li data-start=\"838\" data-end=\"955\">\r\n<p data-start=\"841\" data-end=\"955\"></p></li>', 'en'),
(221, 77, 'دجاج جيرك', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>دجاج مشوي متبل بمزيج من التوابل الجامايكية الحارة والمدخنة مع الفلفل الاسكتلندي.</p>', 'ar'),
(222, 77, 'Pollo Jerk', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pollo a la parrilla marinado en una mezcla picante y ahumada de especias jamaicanas con pimientos Scotch Bonnet.</p>', 'es'),
(223, 78, 'Chicken Vindaloo', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"838\" data-end=\"955\"><p data-start=\"841\" data-end=\"955\">Fiery Goan-style curry with chicken, vinegar, garlic, and lots of chili powder for heat.</p>\r\n</li><p>\r\n</p><li data-start=\"957\" data-end=\"1105\">\r\n<p data-start=\"960\" data-end=\"1105\"></p></li>', 'en'),
(224, 78, 'دجاج فيندالو', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>كاري حار على الطريقة الغوانية مع الدجاج والخل والثوم والكثير من مسحوق الفلفل الحار للحرارة.</p>', 'ar'),
(225, 78, 'Pollo vindaloo', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Curry picante al estilo de Goa con pollo, vinagre, ajo y mucho chile en polvo para darle un toque picante.</p>', 'es'),
(226, 79, 'General Tso’s Chicken', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"1107\" data-end=\"1232\"><p data-start=\"1110\" data-end=\"1232\">Deep-fried chicken tossed in a hot, sweet, and tangy Asian-style sauce with dried chilies.</p>\r\n</li><p>\r\n</p><li data-start=\"1234\" data-end=\"1382\">\r\n<p data-start=\"1238\" data-end=\"1382\"></p></li>', 'en'),
(227, 79, 'دجاج الجنرال تسو', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>دجاج مقلي ممزوج بصلصة آسيوية حارة وحلوة ولذيذة مع الفلفل الحار المجفف.</p>', 'ar'),
(228, 79, 'Pollo del General Tso', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pollo frito bañado en una salsa asiática picante, dulce y picante con chiles secos.</p>', 'es'),
(229, 80, 'Club Sandwich', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Triple-layered sandwich with turkey or chicken, bacon, lettuce, tomato, and mayo, often served with toasted bread.</p>', 'en'),
(230, 80, 'ساندويتش كلوب', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>ساندويتش مكون من ثلاث طبقات من الديك الرومي أو الدجاج، ولحم الخنزير المقدد، والخس، والطماطم، والمايونيز، ويقدم عادة مع الخبز المحمص.</p>', 'ar'),
(231, 80, 'Club Sandwich', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Sándwich de tres capas con pavo o pollo, tocino, lechuga, tomate y mayonesa, a menudo servido con pan tostado.</p>', 'es'),
(232, 81, 'Grilled Cheese', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"366\" data-end=\"483\"><p data-start=\"369\" data-end=\"483\">Melted cheese between two slices of buttered bread, grilled until golden brown and crispy.</p>\r\n</li><p>\r\n</p><li data-start=\"485\" data-end=\"622\">\r\n<p data-start=\"488\" data-end=\"622\"></p></li>', 'en'),
(233, 81, 'جبن مشوي', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>جبن مذاب بين شريحتين من الخبز المدهون بالزبدة، مشوي حتى يصبح لونه بنيًا ذهبيًا ومقرمشًا.</p>', 'ar'),
(234, 81, 'Queso a la parrilla', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Queso fundido entre dos rebanadas de pan con mantequilla, asado hasta quedar dorado y crujiente.</p>', 'es');
INSERT INTO `vendor_item_list_ln` (`id`, `item_id`, `title`, `variants`, `description`, `language`) VALUES
(235, 82, 'Chicken Sandwich', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"485\" data-end=\"622\"><p data-start=\"488\" data-end=\"622\">Breaded or grilled chicken breast with lettuce, tomato, and mayo or sauces, served on a bun or sliced bread.</p>\r\n</li><p>\r\n</p><li data-start=\"624\" data-end=\"730\">\r\n<p data-start=\"627\" data-end=\"730\"></p></li>', 'en'),
(236, 82, 'ساندويتش دجاج', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>صدر دجاج مقلي أو مشوي مع الخس والطماطم والمايونيز أو الصلصات، يقدم على خبز أو شرائح خبز.</p>', 'ar'),
(237, 82, 'Sándwich de pollo', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pechuga de pollo empanizada o a la parrilla con lechuga, tomate y mayonesa o salsas, servida en pan o rebanadas de pan.</p>', 'es'),
(238, 83, 'Egg Salad Sandwich', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"624\" data-end=\"730\"><p data-start=\"627\" data-end=\"730\">Creamy egg salad made with boiled eggs and mayo, served cold on soft bread.</p>\r\n</li><p>\r\n</p><li data-start=\"732\" data-end=\"839\">\r\n<p data-start=\"735\" data-end=\"839\"></p></li>', 'en'),
(239, 83, 'ساندويتش سلطة البيض', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>سلطة البيض الكريمية المصنوعة من البيض المسلوق والمايونيز، تقدم باردة على خبز طري.</p>', 'ar'),
(240, 83, 'Sándwich de ensalada de huevo', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Ensalada cremosa de huevo hecha con huevos cocidos y mayonesa, servida fría sobre pan blando.</p>', 'es'),
(241, 84, 'Tuna Melt', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"732\" data-end=\"839\"><p data-start=\"735\" data-end=\"839\">Tuna salad topped with cheese and melted in a sandwich press or skillet, served warm.</p>\r\n</li><p>\r\n</p><li data-start=\"841\" data-end=\"964\">\r\n<p data-start=\"844\" data-end=\"964\"></p></li>', 'en'),
(242, 84, 'تونة ميلت', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>سلطة التونة المغطاة بالجبن والمذابة في صانعة الساندويتشات أو المقلاة، تقدم دافئة.</p>', 'ar'),
(243, 84, 'Atún fundido', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Ensalada de atún cubierta con queso derretido en una sandwichera o sartén, servida caliente.</p>', 'es'),
(244, 85, 'Philly Cheesesteak', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"841\" data-end=\"964\"><p data-start=\"844\" data-end=\"964\">Thinly sliced beefsteak with sautéed onions and melted cheese, served in a long hoagie roll.</p>\r\n</li><p>\r\n</p><li data-start=\"966\" data-end=\"1073\">\r\n<p data-start=\"969\" data-end=\"1073\"></p></li>', 'en'),
(245, 85, 'فيلي تشيزستيك', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>شرائح رقيقة من لحم البقر مع البصل المقلي والجبن المذاب، تقدم في خبز هوجي طويل.</p>', 'ar'),
(246, 85, 'Filete de queso Filadelfia', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Filete de ternera cortado en rodajas finas con cebollas salteadas y queso derretido, servido en un panecillo largo.</p>', 'es'),
(247, 86, 'Meatball Sub', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"966\" data-end=\"1073\"><p data-start=\"969\" data-end=\"1073\">Italian meatballs with marinara sauce and melted mozzarella, served in a sub roll.</p>\r\n</li><p>\r\n</p><li data-start=\"1075\" data-end=\"1187\">\r\n<p data-start=\"1078\" data-end=\"1187\"></p></li>', 'en'),
(248, 86, 'ساندويتش كرات اللحم', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>كرات اللحم الإيطالية مع صلصة المارينارا وجبنة الموزاريلا المذابة، تقدم في خبز فرعي.</p>', 'ar'),
(249, 86, 'Submarino de albóndigas', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Albóndigas italianas con salsa marinara y mozzarella derretida, servidas en un panecillo.</p>', 'es'),
(250, 87, 'Classic Fried Chicken', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Crispy, golden-brown chicken pieces seasoned with herbs and spices, deep-fried to perfection.</p>', 'en'),
(251, 87, 'دجاج مقلي كلاسيكي', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>قطع دجاج مقرمشة ذات لون ذهبي بني، متبلة بالأعشاب والتوابل، مقلية إلى درجة الكمال.</p>', 'ar'),
(252, 87, 'Pollo frito clásico', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Trozos de pollo crujientes y dorados condimentados con hierbas y especias, fritos a la perfección.</p>', 'es'),
(253, 88, 'Korean Fried Chicken', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"209\" data-end=\"326\"><p data-start=\"212\" data-end=\"326\">Double-fried for extra crispiness and coated in a sweet, spicy, or soy garlic glaze.</p>\r\n</li><p>\r\n</p><li data-start=\"328\" data-end=\"470\">\r\n<p data-start=\"331\" data-end=\"470\"></p></li>', 'en'),
(254, 88, 'دجاج مقلي على الطريقة الكورية', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>مقلي مرتين للحصول على مزيد من القرمشة ومغطى بطبقة من صلصة الثوم الحلوة أو الحارة أو صلصة الصويا.</p>', 'ar'),
(255, 88, 'Pollo frito coreano', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Frito dos veces para que quede más crujiente y cubierto con un glaseado de ajo dulce, picante o de soja.</p>', 'es'),
(256, 89, 'Nashville Hot Chicken', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"328\" data-end=\"470\"><p data-start=\"331\" data-end=\"470\">Southern-style spicy fried chicken dipped in a fiery chili oil blend and served on white bread with pickles.</p>\r\n</li><p>\r\n</p><li data-start=\"472\" data-end=\"596\">\r\n<p data-start=\"475\" data-end=\"596\"></p></li>', 'en'),
(257, 89, 'دجاج ناشفيل الحار', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>دجاج مقلي حار على الطريقة الجنوبية، مغموس في مزيج من زيت الفلفل الحار ويقدم على خبز أبيض مع مخلل.</p>', 'ar'),
(258, 89, 'Pollo picante de Nashville', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pollo frito picante al estilo sureño sumergido en una mezcla de aceite de chile picante y servido en pan blanco con pepinillos.</p>', 'es'),
(259, 90, 'Popcorn Chicken', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"472\" data-end=\"596\"><p data-start=\"475\" data-end=\"596\">Bite-sized, breaded chicken nuggets, crunchy on the outside and juicy inside—perfect as a snack.</p>\r\n</li><p>\r\n</p><li data-start=\"598\" data-end=\"729\">\r\n<p data-start=\"601\" data-end=\"729\"></p></li>', 'en'),
(260, 90, 'دجاج الفشار', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>قطع دجاج صغيرة الحجم ومغطاة بالبقسماط، مقرمشة من الخارج وعصيرة من الداخل - مثالية كوجبة خفيفة.</p>', 'ar'),
(261, 90, 'Pollo palomitas de maíz', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Nuggets de pollo empanizados del tamaño de un bocado, crujientes por fuera y jugosos por dentro, perfectos como refrigerio.</p>', 'es'),
(262, 91, 'Chicken Tenders', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"598\" data-end=\"729\"><p data-start=\"601\" data-end=\"729\">Long, boneless strips of fried chicken, usually served with dipping sauces like honey mustard or ranch.</p>\r\n</li><p>\r\n</p><li data-start=\"731\" data-end=\"857\">\r\n<p data-start=\"734\" data-end=\"857\"></p></li>', 'en'),
(263, 91, 'قطع دجاج طرية', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>شرائح طويلة من الدجاج المقلي منزوعة العظم، تقدم عادة مع صلصات الغمس مثل صلصة الخردل والعسل أو الرانش.</p>', 'ar'),
(264, 91, 'Tiras de pollo', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Tiras largas y deshuesadas de pollo frito, generalmente servidas con salsas para mojar como mostaza y miel o ranch.</p>', 'es'),
(265, 92, 'Buffalo Wings', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"731\" data-end=\"857\"><p data-start=\"734\" data-end=\"857\">Deep-fried chicken wings tossed in a tangy buffalo sauce, served with blue cheese or ranch dressing</p></li>', 'en'),
(266, 92, 'أجنحة الجاموس', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>أجنحة دجاج مقلية مغموسة في صلصة بافالو لاذعة، تقدم مع الجبن الأزرق أو صلصة الرانش</p>', 'ar'),
(267, 92, 'Alitas de búfalo', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Alitas de pollo fritas bañadas en una salsa picante de búfalo, servidas con queso azul o aderezo ranch.</p>', 'es'),
(268, 93, 'Buttermilk Fried Chicken', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"859\" data-end=\"994\"><p data-start=\"862\" data-end=\"994\">Chicken marinated in seasoned buttermilk for tenderness, then fried for a crispy, flavorful crust.</p>\r\n</li><p>\r\n</p><li data-start=\"996\" data-end=\"1162\">\r\n<p data-start=\"999\" data-end=\"1162\"></p></li>', 'en'),
(269, 93, 'دجاج مقلي باللبن الرائب', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>دجاج متبل باللبن الرائب المتبل ليصبح طريًا، ثم مقليًا للحصول على قشرة مقرمشة ولذيذة.</p>', 'ar'),
(270, 93, 'Pollo frito con suero de leche', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pollo marinado en suero de leche condimentado para que quede tierno, luego frito para obtener una corteza crujiente y sabrosa.</p>', 'es'),
(271, 94, 'Classic Cheeseburger', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"73\" data-end=\"204\"><p data-start=\"76\" data-end=\"204\">Juicy beef patty topped with melted cheese, lettuce, tomato, onions, and pickles in a toasted bun.</p>\r\n</li><p>\r\n</p><li data-start=\"206\" data-end=\"341\">\r\n<p data-start=\"209\" data-end=\"341\"></p></li>', 'en'),
(272, 94, 'تشيز برجر كلاسيكي', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>فطيرة لحم بقري شهية مغطاة بالجبن الذائب والخس والطماطم والبصل والمخللات في خبز محمص.</p>', 'ar'),
(273, 94, 'Hamburguesa con queso clásica', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Jugosa hamburguesa de carne cubierta con queso derretido, lechuga, tomate, cebolla y pepinillos en un pan tostado.</p>', 'es'),
(274, 95, 'Bacon Double Cheeseburger', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"206\" data-end=\"341\"><p data-start=\"209\" data-end=\"341\">Two beef patties layered with cheddar cheese and crispy bacon, served with BBQ sauce and veggies.</p>\r\n</li><p>\r\n</p><li data-start=\"343\" data-end=\"462\">\r\n<p data-start=\"346\" data-end=\"462\"></p></li>', 'en'),
(275, 95, 'برجر مزدوج بالجبن والبيكون', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>قطعتين من لحم البقر مغطاة بجبنة الشيدر ولحم الخنزير المقدد المقرمش، تقدم مع صلصة الشواء والخضروات.</p>', 'ar'),
(276, 95, 'Hamburguesa doble con queso y tocino', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Dos hamburguesas de carne con capas de queso cheddar y tocino crujiente, servidas con salsa barbacoa y verduras.</p>', 'es'),
(277, 96, 'Chicken Crispy Burger', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"343\" data-end=\"462\"><p data-start=\"346\" data-end=\"462\">Breaded and fried chicken fillet with mayo, lettuce, and tomato in a soft sesame bun.</p>\r\n</li><p>\r\n</p><li data-start=\"464\" data-end=\"581\">\r\n<p data-start=\"467\" data-end=\"581\"></p></li>', 'en'),
(278, 96, 'برجر دجاج مقرمش', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>فيليه دجاج مقلي ومغطى بالبقسماط مع المايونيز والخس والطماطم في كعكة السمسم الناعمة.</p>', 'ar'),
(279, 96, 'Hamburguesa crujiente de pollo', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Filete de pollo empanizado y frito con mayonesa, lechuga y tomate en un pan suave de sésamo.</p>', 'es'),
(280, 97, 'Veggie Burger', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"464\" data-end=\"581\"><p data-start=\"467\" data-end=\"581\">Plant-based patty made with vegetables, beans, or soy, served with fresh greens and sauces.</p></li>', 'en'),
(281, 97, 'برجر نباتي', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>فطيرة نباتية مصنوعة من الخضروات والفاصوليا أو الصويا، تقدم مع الخضروات الطازجة والصلصات.</p>', 'ar'),
(282, 97, 'Hamburguesa vegetariana', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Hamburguesa a base de plantas elaborada con vegetales, frijoles o soja, servida con verduras frescas y salsas.</p>', 'es'),
(283, 98, 'Mushroom Swiss Burger', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"703\" data-end=\"813\"><p data-start=\"706\" data-end=\"813\"><br data-start=\"731\" data-end=\"734\">\r\nBeef patty topped with sautéed mushrooms and Swiss cheese, with garlic mayo.</p>\r\n</li><p>\r\n</p><li data-start=\"815\" data-end=\"922\">\r\n<p data-start=\"818\" data-end=\"922\"></p></li>', 'en'),
(284, 98, 'برجر الفطر السويسري', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>فطيرة لحم بقري مغطاة بالفطر المقلي والجبن السويسري، مع المايونيز بالثوم.</p>', 'ar'),
(285, 98, 'Hamburguesa suiza de champiñones', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Hamburguesa de carne cubierta con champiñones salteados y queso suizo, con mayonesa de ajo.</p>', 'es'),
(286, 99, 'Fish Fillet Burger', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"815\" data-end=\"922\"><p data-start=\"818\" data-end=\"922\"><br data-start=\"840\" data-end=\"843\">\r\nGolden fried fish fillet, lettuce, and tartar sauce served in a steamed bun.</p>\r\n</li><p>\r\n</p><li data-start=\"924\" data-end=\"1029\">\r\n<p data-start=\"927\" data-end=\"1029\"></p></li>', 'en'),
(287, 99, 'برجر فيليه السمك', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>فيليه السمك المقلي الذهبي، الخس، وصلصة التارتار، يقدم في خبز مطهو على البخار.</p>', 'ar'),
(288, 99, 'Hamburguesa de filete de pescado', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Filete de pescado frito dorado, lechuga y salsa tártara servido en un pan al vapor.</p>', 'es'),
(289, 100, 'Grilled Chicken Burger', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"1031\" data-end=\"1162\"><p data-start=\"1034\" data-end=\"1162\"><br data-start=\"1060\" data-end=\"1063\">\r\nMarinated grilled chicken breast, lettuce, tomato, and honey mustard sauce in a whole wheat bun.</p>\r\n</li><p>\r\n</p><li data-start=\"1164\" data-end=\"1292\">\r\n<p data-start=\"1168\" data-end=\"1292\"></p></li>', 'en'),
(290, 100, 'برجر دجاج مشوي', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>صدر دجاج مشوي متبل، خس، طماطم، وصلصة الخردل والعسل في خبز قمح كامل.</p>', 'ar'),
(291, 100, 'Hamburguesa de pollo a la parrilla', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pechuga de pollo marinada a la parrilla, lechuga, tomate y salsa de mostaza y miel en un pan integral.</p>', 'es'),
(292, 101, 'Paneer Tikka Burger ', '{\"variant_name\":\"\",\"variant_options\":[]}', '<ol data-start=\"73\" data-end=\"1292\"><li data-start=\"1164\" data-end=\"1292\"><p data-start=\"1168\" data-end=\"1292\">Indian-style grilled paneer with spicy tikka masala, onions, and mint chutney in a bun.</p>\r\n</li>\r\n</ol>', 'en'),
(293, 101, '', '{\"variant_name\":\"\",\"variant_options\":[]}', '', 'ar'),
(294, 101, '', '{\"variant_name\":\"\",\"variant_options\":[]}', '', 'es'),
(295, 102, 'Samsung Galaxy S24 FE', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>The Samsung Galaxy S24 FE is a feature-rich, powerful smartphone that offers flagship-level features at a more affordable price. The Samsung Galaxy S24 FE Smartphone is driven by the cutting-edge Exynos 2400e chipset, which is developed on an innovative 4nm process. It has a highly efficient 10-core CPU (1x3.1GHz, 2x2.9GHz, 3x2.6GHz, 4x1.95GHz) and the powerful Xclipse 940 GPU. This hardware configuration assures that the Samsung Galaxy S24 FE Mobile can perform demanding tasks like mobile gaming, video editing, and multitasking without difficulty.</p>', 'en'),
(296, 102, 'سامسونج جالكسي S24 FE', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>هاتف سامسونج جالاكسي S24 FE هاتف ذكي قوي وغني بالميزات، يقدم ميزات رائدة بسعر مناسب. يعمل الهاتف بمعالج Exynos 2400e المتطور، والمطور بتقنية 4 نانومتر المبتكرة. يحتوي على وحدة معالجة مركزية عالية الكفاءة بعشرة أنوية (1×3.1 جيجاهرتز، 2×2.9 جيجاهرتز، 3×2.6 جيجاهرتز، 4×1.95 جيجاهرتز) ووحدة معالجة الرسومات القوية Xclipse 940. يضمن هذا التكوين القوي أداء هاتف سامسونج جالاكسي S24 FE للمهام الصعبة، مثل ألعاب الهاتف، وتحرير الفيديو، وتعدد المهام، بسلاسة.</p>', 'ar'),
(297, 102, 'Samsung Galaxy S24 FE', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El Samsung Galaxy S24 FE es un smartphone potente y repleto de funciones que ofrece prestaciones de gama alta a un precio asequible. El Samsung Galaxy S24 FE está equipado con el vanguardista chipset Exynos 2400e, desarrollado mediante un innovador proceso de 4 nm. Cuenta con una CPU de 10 núcleos de alta eficiencia (1x3.1 GHz, 2x2.9 GHz, 3x2.6 GHz, 4x1.95 GHz) y la potente GPU Xclipse 940. Esta configuración de hardware garantiza que el Samsung Galaxy S24 FE Mobile pueda realizar tareas exigentes como juegos móviles, edición de vídeo y multitarea sin dificultad.</p>', 'es'),
(298, 103, 'iPhone 15 Plus', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">The back glass of the Apple </span><strong style=\"margin: 0px; padding: 0px; color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">iPhone 15 Plus</strong><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\"> has been creatively redesigned with color infused throughout. Because of its innovative twin ion-exchange glass technology and aerospace-grade aluminum casing, the iPhone 15 is incredibly robust. Its front Ceramic Shield is stronger than any smartphone glass.</span></p>', 'en'),
(299, 103, 'آيفون 15 بلس', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>أُعيد تصميم الزجاج الخلفي لهاتف Apple iPhone 15 Plus بإبداع، مُدمجًا الألوان في جميع أرجائه. بفضل تقنية زجاج التبادل الأيوني المزدوج المبتكرة وهيكله المصنوع من الألومنيوم عالي الجودة، يتميز iPhone 15 بمتانة فائقة. أما درعه الخزفي الأمامي، فهو أقوى من أي زجاج هاتف ذكي.</p>', 'ar'),
(300, 103, 'iPhone 15 Plus', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El cristal trasero del Apple iPhone 15 Plus ha sido rediseñado con creatividad, con un toque de color en todo su interior. Gracias a su innovadora tecnología de intercambio iónico doble y a su carcasa de aluminio de grado aeroespacial, el iPhone 15 es increíblemente robusto. Su escudo cerámico frontal es más resistente que el cristal de cualquier smartphone.</p>', 'es'),
(301, 104, 'iPhone 14 Pro Max', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">The iPhone 14 Pro Max is the latest model of the iPhone series, featuring the latest technology and advanced features that are designed to provide users with a seamless and unparalleled mobile experience. The device is powered by the latest A16 Bionic chip, providing exceptional performance and power efficiency.</span></p>', 'en'),
(302, 104, 'آيفون 14 برو ماكس', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>آيفون 14 برو ماكس هو أحدث طراز من سلسلة آيفون، يتميز بأحدث التقنيات والميزات المتقدمة المصممة لتزويد المستخدمين بتجربة استخدام سلسة لا مثيل لها. يعمل الجهاز بأحدث شريحة A16 Bionic، مما يوفر أداءً استثنائيًا وكفاءة عالية في استهلاك الطاقة.</p>', 'ar'),
(303, 104, 'iPhone 14 Pro Max', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El iPhone 14 Pro Max es el último modelo de la serie iPhone, con tecnología de vanguardia y funciones avanzadas diseñadas para brindar a los usuarios una experiencia móvil fluida e inigualable. El dispositivo está equipado con el último chip A16 Bionic, que proporciona un rendimiento y una eficiencia energética excepcionales.</p>', 'es'),
(304, 105, 'Google Pixel 7 Pro', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>The Google Pixel 7 Pro comes with a 6.7-inch OLED display with a QHD+ resolution of 1440 x 3120 pixels with a 19.5:9 aspect ratio and a pixel density of around 512 ppi. It also has HDR and Corning Gorilla Glass Victus protection, as well as an always-on display feature. This phone is powered by Google Tensor G2 5nm Octa-core Processor for fast performance.</p>', 'en'),
(305, 105, 'جوجل بيكسل 7 برو', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>يأتي هاتف جوجل بيكسل 7 برو بشاشة OLED مقاس 6.7 بوصة بدقة QHD+ تبلغ 1440 × 3120 بكسل، بنسبة عرض إلى ارتفاع تبلغ 19.5:9، وكثافة بكسلات تبلغ حوالي 512 بكسل لكل بوصة. كما يدعم الهاتف تقنية HDR وطبقة حماية من زجاج Corning Gorilla Glass Victus، بالإضافة إلى ميزة الشاشة الدائمة. يعمل هذا الهاتف بمعالج جوجل Tensor G2 ثماني النواة بتقنية 5 نانومتر لأداء سريع.</p>', 'ar'),
(306, 105, 'Google Pixel 7 Pro', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El Google Pixel 7 Pro viene con una pantalla OLED de 6.7 pulgadas con una resolución QHD+ de 1440 x 3120 píxeles, una relación de aspecto de 19.5:9 y una densidad de píxeles de aproximadamente 512 ppp. También cuenta con protección HDR y Corning Gorilla Glass Victus, además de pantalla siempre activa. Este teléfono incorpora el procesador Google Tensor G2 de ocho núcleos de 5 nm para un rendimiento rápido.</p>', 'es'),
(307, 106, 'Google Pixel 8 Pro', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">The Google </span><span style=\"margin: 0px; padding: 0px; color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255); font-weight: bold;\">Pixel 8 Pro</span><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\"> is a flagship Android smartphone that redefines excellence in the world of mobile technology. With a substantial 128GB of storage and an impressive 12GB of RAM, this device ensures that you have ample space for your files and delivers seamless multitasking performance. The Pixel 8 Pro boasts a magnificent 6.7-inch HDR10+ OLED display, offering vibrant colors and sharp contrast with a refresh rate of up to 120 Hz, ensuring a visually captivating experience whether you\'re watching videos, browsing the web, or gaming.</span></p>', 'en'),
(308, 106, 'جوجل بيكسل 8 برو', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>هاتف جوجل بيكسل 8 برو هو هاتف ذكي رائد يعمل بنظام أندرويد، يُعيد تعريف التميز في عالم تكنولوجيا الهواتف المحمولة. بفضل سعة تخزين كبيرة تبلغ 128 جيجابايت وذاكرة وصول عشوائي (RAM) مذهلة تبلغ 12 جيجابايت، يضمن لك هذا الجهاز مساحة تخزين واسعة لملفاتك، ويمنحك أداءً سلسًا في تعدد المهام. يتميز بيكسل 8 برو بشاشة OLED رائعة مقاس 6.7 بوصة بتقنية HDR10+، تُقدم ألوانًا نابضة بالحياة وتباينًا حادًا مع معدل تحديث يصل إلى 120 هرتز، مما يضمن تجربة بصرية آسرة سواء كنت تشاهد مقاطع الفيديو أو تتصفح الويب أو تلعب الألعاب.</p>', 'ar'),
(309, 106, 'Google Pixel 8 Pro', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El Google Pixel 8 Pro es un smartphone Android insignia que redefine la excelencia en el mundo de la tecnología móvil. Con una sustancial capacidad de almacenamiento de 128 GB y una impresionante memoria RAM de 12 GB, este dispositivo te garantiza un amplio espacio para tus archivos y un rendimiento multitarea impecable. El Pixel 8 Pro cuenta con una magnífica pantalla OLED HDR10+ de 6.7 pulgadas, que ofrece colores vibrantes y un contraste nítido con una frecuencia de actualización de hasta 120 Hz, lo que garantiza una experiencia visualmente cautivadora, ya sea que veas videos, navegues por internet o juegues.</p>', 'es'),
(310, 107, 'Xiaomi Redmi 14C', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">The </span><strong style=\"margin: 0px; padding: 0px; color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">Xiaomi Redmi 14C</strong><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\"> is designed to provide a seamless and powerful smartphone experience. Featuring a 6.71-inch HD+ LCD display, this phone offers immersive visuals that bring your content to life. Powered by the MediaTek Helio G70 processor, the Redmi 14C ensures smooth performance whether you\'re gaming, streaming, or multitasking. With 6GB of RAM and 128GB of internal storage, you\'ll have ample space for all your apps, photos, and videos, while enjoying fast and responsive performance. The sleek design and lightweight build make it easy to carry and use, providing both style and functionality in one package.</span></p>', 'en'),
(311, 107, 'شاومي ريدمي 14C', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>صُمم هاتف شاومي ريدمي 14C ليمنحك تجربة استخدام سلسة وقوية. يتميز بشاشة LCD عالية الدقة مقاس 6.71 بوصة، ما يوفر صورًا غامرة تضفي حيوية على محتواك. يعمل ريدمي 14C بمعالج MediaTek Helio G70، ويضمن لك أداءً سلسًا سواءً كنت تلعب أو تشاهد مقاطع الفيديو أو تقوم بمهام متعددة. مع ذاكرة وصول عشوائي (RAM) بسعة 6 جيجابايت وذاكرة تخزين داخلية بسعة 128 جيجابايت، ستتوفر لديك مساحة كافية لجميع تطبيقاتك وصورك ومقاطع الفيديو، مع الاستمتاع بأداء سريع وسريع الاستجابة. تصميمه الأنيق ووزنه الخفيف يجعلانه سهل الحمل والاستخدام، ويجمع بين الأناقة والوظائف في جهاز واحد.</p>', 'ar'),
(312, 107, 'Xiaomi Redmi 14C', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El Xiaomi Redmi 14C está diseñado para brindar una experiencia de smartphone fluida y potente. Con una pantalla LCD HD+ de 6.71 pulgadas, este teléfono ofrece imágenes inmersivas que dan vida a tu contenido. Equipado con el procesador MediaTek Helio G70, el Redmi 14C garantiza un rendimiento fluido, ya sea que juegues, transmitas contenido o realices múltiples tareas. Con 6 GB de RAM y 128 GB de almacenamiento interno, tendrás amplio espacio para todas tus aplicaciones, fotos y videos, a la vez que disfrutas de un rendimiento rápido y con gran capacidad de respuesta. Su diseño elegante y construcción ligera lo hacen fácil de transportar y usar, ofreciendo estilo y funcionalidad en un solo paquete.</p>', 'es'),
(313, 108, 'Xiaomi Redmi Note 14', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">The Xiaomi </span><strong style=\"margin: 0px; padding: 0px; color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">Redmi Note 14</strong><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\"> is a feature-rich affordable smartphone with impressive performance and multimedia capabilities. It features a magnificent 6.67-inch FHD+ AMOLED display with a resolution of 2400 x 1080 pixels, a smooth 120Hz refresh rate, and a peak brightness of 1800 nits, all protected by Gorilla Glass 5. The Xiaomi Redmi Note 14 is powered by the efficient MediaTek Helio G99 Ultra chipset, which has an octa-core processor clocked up to 2.2GHz and a Mali-G57 MC2 GPU for better graphics, resulting in fluid multitasking and gaming experiences.</span></p>', 'en'),
(314, 108, 'شاومي ريدمي نوت 14', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>هاتف شاومي ريدمي نوت 14 هو هاتف ذكي غني بالميزات وبسعر معقول، يتميز بأداء مذهل وقدرات وسائط متعددة رائعة. يتميز بشاشة AMOLED رائعة مقاس 6.67 بوصة بدقة FHD+ تبلغ 2400 × 1080 بكسل، ومعدل تحديث سلس يبلغ 120 هرتز، وسطوع يصل إلى 1800 شمعة، وجميعها محمية بزجاج غوريلا 5. يعمل هاتف شاومي ريدمي نوت 14 بمعالج ميديا ​​تيك هيليو G99 ألترا الفعال، والذي يحتوي على معالج ثماني النواة بتردد يصل إلى 2.2 جيجاهرتز ووحدة معالجة رسومية Mali-G57 MC2 لتحسين الرسومات، مما يوفر تجربة تعدد مهام وألعاب سلسة.</p>', 'ar'),
(315, 108, 'Xiaomi Redmi Note 14', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El Xiaomi Redmi Note 14 es un smartphone asequible y repleto de funciones, con un rendimiento impresionante y capacidades multimedia. Cuenta con una magnífica pantalla AMOLED FHD+ de 6,67 pulgadas con una resolución de 2400 x 1080 píxeles, una fluida frecuencia de actualización de 120 Hz y un brillo máximo de 1800 nits, todo ello protegido por Gorilla Glass 5. El Xiaomi Redmi Note 14 está equipado con el eficiente chipset MediaTek Helio G99 Ultra, que cuenta con un procesador de ocho núcleos con una velocidad de reloj de hasta 2,2 GHz y una GPU Mali-G57 MC2 para una mejor experiencia gráfica, lo que resulta en una multitarea y juegos fluidos.</p>', 'es'),
(316, 109, 'OnePlus Nord N30 SE 5G', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">The OnePlus </span><strong style=\"margin: 0px; padding: 0px; color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">Nord N30 SE </strong><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">is a stunning combination of cutting-edge technology and stylish design, created to take your mobile experience to new levels. With a 6.72\" FHD+ display with a resolution of 2400x1080 and a pixel density of 391 PPI, this OnePlus smartphone provides immersive graphics with astonishing clarity and brilliant colors, bringing every movie, game, and photo to life in beautiful detail. The OnePlus Nord N30 SE is powered by the modern Mediatek Dimensity 6020 (7 nm) CPU, which ensures smooth and responsive performance for all of your everyday needs, from app multitasking to high-end gaming. </span></p>', 'en'),
(317, 109, 'ون بلس نورد N30 SE 5G', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>هاتف ون بلس نورد N30 SE هو مزيجٌ رائعٌ من التكنولوجيا المتطورة والتصميم الأنيق، مُصممٌ ليأخذ تجربة استخدام هاتفك المحمول إلى آفاقٍ جديدة. بفضل شاشة FHD+ مقاس 6.72 بوصة بدقة 2400×1080 وكثافة بكسلات 391 بكسل لكل بوصة، يُقدم هذا الهاتف الذكي من ون بلس رسوماتٍ غامرة بوضوحٍ مذهل وألوانٍ زاهية، مما يُضفي حيويةً على كل فيلمٍ ولعبةٍ وصورةٍ بتفاصيلها الجميلة. يعمل ون بلس نورد N30 SE بمعالج Mediatek Dimensity 6020 الحديث (7 نانومتر)، مما يضمن أداءً سلسًا وسريع الاستجابة لجميع احتياجاتك اليومية، من تعدد مهام التطبيقات إلى الألعاب عالية الأداء.</p>', 'ar'),
(318, 109, 'OnePlus Nord N30 SE 5G', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El OnePlus Nord N30 SE es una impresionante combinación de tecnología de vanguardia y diseño elegante, creado para llevar tu experiencia móvil a un nuevo nivel. Con una pantalla FHD+ de 6.72\" con una resolución de 2400x1080 y una densidad de píxeles de 391 ppp, este smartphone OnePlus ofrece gráficos inmersivos con una claridad asombrosa y colores brillantes, dando vida a cada película, juego y foto con un detalle espectacular. El OnePlus Nord N30 SE está equipado con la moderna CPU Mediatek Dimensity 6020 (7 nm), que garantiza un rendimiento fluido y con gran capacidad de respuesta para todas tus necesidades diarias, desde la multitarea de aplicaciones hasta los juegos de alta gama.</p>', 'es'),
(319, 110, 'OnePlus Nord 4', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">The OnePlus </span><strong style=\"margin: 0px; padding: 0px; color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">Nord 4</strong><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">, is an excellent mid-range OnePlus smartphone that flawlessly combines modern features with a sleek design to provide a remarkable user experience. This OnePlus Mobile Phone boasts a magnificent 6.74-inch Fluid AMOLED display with a resolution of 1240 x 2772 pixels, resulting in bright colors and clear images. The display offers 120Hz refresh rate and HDR10+, offering a seamless and immersive viewing experience. </span></p>', 'en'),
(320, 110, 'ون بلس نورد 4', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>هاتف OnePlus Nord 4، هاتف ذكي ممتاز من الفئة المتوسطة من OnePlus، يجمع ببراعة بين الميزات العصرية والتصميم الأنيق ليقدم تجربة مستخدم استثنائية. يتميز هذا الهاتف بشاشة Fluid AMOLED رائعة مقاس 6.74 بوصة بدقة 1240 × 2772 بكسل، مما يوفر ألوانًا زاهية وصورًا واضحة. تتميز الشاشة بمعدل تحديث 120 هرتز وتقنية HDR10+، مما يوفر تجربة مشاهدة سلسة وغامرة.</p>', 'ar'),
(321, 110, 'OnePlus Nord 4', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El OnePlus Nord 4 es un excelente smartphone OnePlus de gama media que combina a la perfección funciones modernas con un diseño elegante para ofrecer una experiencia de usuario excepcional. Este teléfono OnePlus cuenta con una magnífica pantalla Fluid AMOLED de 6,74 pulgadas con una resolución de 1240 x 2772 píxeles, que ofrece colores brillantes e imágenes nítidas. La pantalla ofrece una frecuencia de actualización de 120 Hz y HDR10+, ofreciendo una experiencia visual fluida e inmersiva.</p>', 'es'),
(322, 111, 'Realme Note 60x', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">The </span><strong style=\"margin: 0px; padding: 0px; color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">Realme Note 60x</strong><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\"> is a smartphone that offers a smooth experience with an attractive modern design for the modern Customers. This Realme Smartphone has a 6.74-inch IPS LCD display, with a smooth 90Hz refresh rate, provides bright and smooth visuals, making every interaction with your Realme Mobile phone more enjoyable. The Unisoc Tiger T612 processor, paired with 4GB of RAM that can be expanded with Virtula RAM, delivers efficient performance and flawless multitasking, ensuring that your programs operate smoothly on the Realme Note 60x. </span></p>', 'en'),
(323, 111, 'ريلمي نوت 60x', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>هاتف Realme Note 60x هو هاتف ذكي يوفر تجربة استخدام سلسة بتصميم عصري جذاب للعملاء العصريين. يتميز هذا الهاتف بشاشة IPS LCD مقاس 6.74 بوصة، بمعدل تحديث سلس يبلغ 90 هرتز، مما يوفر صورًا ساطعة وسلسة، مما يجعل كل تفاعل مع هاتف Realme Mobile أكثر متعة. يوفر معالج Unisoc Tiger T612، إلى جانب ذاكرة وصول عشوائي (RAM) سعة 4 جيجابايت قابلة للتوسيع باستخدام ذاكرة Virtula RAM، أداءً فعالاً وتعدد مهام سلسًا، مما يضمن تشغيل برامجك بسلاسة على هاتف Realme Note 60x.</p>', 'ar'),
(324, 111, 'Realme Note 60x', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El Realme Note 60x es un smartphone que ofrece una experiencia fluida con un diseño moderno y atractivo para los clientes actuales. Este smartphone Realme cuenta con una pantalla IPS LCD de 6.74 pulgadas con una frecuencia de actualización de 90 Hz que proporciona imágenes nítidas y brillantes, haciendo que cada interacción con tu Realme sea más placentera. El procesador Unisoc Tiger T612, junto con 4 GB de RAM ampliables con Virtula RAM, ofrece un rendimiento eficiente y una multitarea impecable, garantizando que tus programas funcionen con fluidez en el Realme Note 60x.</p>', 'es'),
(325, 112, 'Vivo Y03t', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">The Vivo </span><strong style=\"margin: 0px; padding: 0px; color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">Y03t</strong><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\"> is an affordable </span><a href=\"https://www.startech.com.bd/mobile-phone\" target=\"\" style=\"margin: 0px; padding: 0px; text-decoration-line: underline; background-color: rgb(255, 255, 255); color: rgb(0, 0, 0); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px;\">smartphone </a><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">that comes with the potent T612 processor, which is based on a 12 nm production node and has an octa-core CPU design with two cores clocked at 1.8 GHz and six cores at 1.8 GHz. Together with 64 GB or 128GB of eMMC 5.1 ROM that can be expanded to 1 TB, it comes with 4 GB of LPDDR4X RAM and an extra 4 GB of expandable RAM. Long-lasting use is ensured by the phone\'s sturdy 5000 mAh Li-ion battery, which supports 15W charging.</span></p>', 'en'),
(326, 112, 'فيفو Y03t', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>هاتف Vivo Y03t هو هاتف ذكي اقتصادي، مزود بمعالج T612 قوي، مبني على تقنية تصنيع 12 نانومتر، ووحدة معالجة مركزية ثماني النواة، نواتان بتردد 1.8 جيجاهرتز وستة أنوية بتردد 1.8 جيجاهرتز. يأتي الهاتف مع ذاكرة وصول عشوائي (RAM) من نوع eMMC 5.1 بسعة 64 أو 128 جيجابايت قابلة للتوسيع حتى 1 تيرابايت، وذاكرة وصول عشوائي (RAM) من نوع LPDDR4X بسعة 4 جيجابايت، وذاكرة وصول عشوائي (RAM) قابلة للتوسيع بسعة 4 جيجابايت إضافية. يضمن الهاتف استخدامًا طويل الأمد بفضل بطارية ليثيوم أيون قوية بسعة 5000 مللي أمبير/ساعة، تدعم الشحن بقوة 15 واط.</p>', 'ar'),
(327, 112, 'Vivo Y03t', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El Vivo Y03t es un smartphone asequible que incorpora el potente procesador T612, basado en un nodo de producción de 12 nm y con un diseño de CPU de ocho núcleos con dos y seis núcleos a 1,8 GHz. Además, cuenta con 64 GB o 128 GB de ROM eMMC 5.1 ampliable a 1 TB, 4 GB de RAM LPDDR4X y 4 GB adicionales de RAM ampliables. Su robusta batería de iones de litio de 5000 mAh, compatible con carga de 15 W, garantiza un uso prolongado.</p>', 'es'),
(328, 113, 'OPPO Reno13', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">The OPPO </span><strong style=\"margin: 0px; padding: 0px; color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">Reno13</strong><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\"> is a cutting-edge smartphone that blends powerful technologies and a stylish design. Oppo Reno13 has a 6.59-inch AMOLED display with a 120Hz ultra-high refresh rate, which ensures smooth and immersive graphics. The Oppo Reno13 Mobile phone is built on the MediaTek Dimensity 8350 platform, which ensures rapid performance and efficiency. Oppo Reno13 has 8GB of RAM and 256GB of internal storage, which provides plenty of memory and capacity for all of your apps and media</span></p>', 'en'),
(329, 113, 'ممن لهم رينو13', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>هاتف أوبو رينو 13 هو هاتف ذكي متطور يجمع بين التقنيات المتطورة والتصميم الأنيق. يتميز بشاشة AMOLED مقاس 6.59 بوصة بمعدل تحديث فائق 120 هرتز، مما يضمن رسومات سلسة وغامرة. صُمم هاتف أوبو رينو 13 المحمول بمعالج MediaTek Dimensity 8350، مما يضمن أداءً سريعًا وكفاءة عالية. يحتوي أوبو رينو 13 على ذاكرة وصول عشوائي (RAM) بسعة 8 جيجابايت وذاكرة تخزين داخلية بسعة 256 جيجابايت، مما يوفر مساحة تخزين رحبة لجميع تطبيقاتك ووسائطك.</p>', 'ar'),
(330, 113, 'OPPO Reno13', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El OPPO Reno13 es un smartphone de vanguardia que combina tecnologías potentes con un diseño elegante. Cuenta con una pantalla AMOLED de 6,59 pulgadas con una frecuencia de actualización ultraalta de 120 Hz, que garantiza gráficos fluidos e inmersivos. El Oppo Reno13 está basado en la plataforma MediaTek Dimensity 8350, que garantiza un rendimiento y eficiencia rápidos. Cuenta con 8 GB de RAM y 256 GB de almacenamiento interno, lo que proporciona una memoria y capacidad de sobra para todas tus aplicaciones y contenido multimedia.</p>', 'es'),
(331, 114, 'Apple Watch Series 9', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><br data-start=\"110\" data-end=\"113\">\r\nA premium smartwatch with advanced health tracking, ECG, blood oxygen monitoring, and deep iPhone integration. Ideal for Apple users.</p>', 'en'),
(332, 114, 'ساعة Apple Watch Series 9', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>ساعة ذكية فاخرة مزودة بتتبع صحي متقدم، وتخطيط كهربية القلب، ومراقبة أكسجين الدم، وتكامل عميق مع أجهزة iPhone. مثالية لمستخدمي Apple.</p>', 'ar'),
(333, 114, 'Apple Watch Series 9', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Un smartwatch premium con monitorización avanzada de salud, ECG, monitorización de oxígeno en sangre y una completa integración con iPhone. Ideal para usuarios de Apple.</p>', 'es'),
(334, 115, 'Samsung Galaxy Watch 6', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"251\" data-end=\"395\"><p data-start=\"254\" data-end=\"395\">Sleek and powerful with a rotating bezel, fitness tracking, sleep analysis, and strong Android compatibility.</p>\r\n</li><p>\r\n</p><li data-start=\"397\" data-end=\"536\">\r\n<p data-start=\"400\" data-end=\"536\"></p></li>', 'en'),
(335, 115, 'ساعة سامسونج جالكسي واتش 6', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>أنيق وقوي مع إطار دوار وميزة تتبع اللياقة البدنية وتحليل النوم والتوافق القوي مع نظام Android.</p>', 'ar'),
(336, 115, 'Samsung Galaxy Watch 6', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Elegante y potente, con bisel giratorio, seguimiento de actividad física, análisis del sueño y fuerte compatibilidad con Android.</p>', 'es'),
(337, 116, 'Google Pixel Watch 2', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"397\" data-end=\"536\"><p data-start=\"400\" data-end=\"536\"><br data-start=\"424\" data-end=\"427\">\r\nStylish with Fitbit health features, deep Google ecosystem integration, and excellent Wear OS performance.</p>\r\n</li><p>\r\n</p><li data-start=\"538\" data-end=\"672\">\r\n<p data-start=\"541\" data-end=\"672\"></p></li>', 'en'),
(338, 116, 'ساعة جوجل بيكسل 2', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>أنيقة مع ميزات Fitbit الصحية والتكامل العميق مع نظام Google البيئي وأداء Wear OS الممتاز.</p>', 'ar'),
(339, 116, 'Google Pixel Watch 2', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Elegante con funciones de salud de Fitbit, profunda integración con el ecosistema de Google y excelente rendimiento de Wear OS.</p>', 'es'),
(340, 117, 'Garmin Forerunner 965', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"538\" data-end=\"672\"><p data-start=\"541\" data-end=\"672\"><br data-start=\"566\" data-end=\"569\">\r\nGPS-focused watch for runners and athletes. Offers VO2 max, advanced metrics, and long battery life.</p>\r\n</li><p>\r\n</p><li data-start=\"674\" data-end=\"813\">\r\n<p data-start=\"677\" data-end=\"813\"></p></li>', 'en'),
(341, 117, 'جارمين فور رانر 965', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>ساعة مُركّزة على نظام تحديد المواقع العالمي (GPS) للعدائين والرياضيين. تُقدّم أقصى استهلاك للأكسجين (VO2 max)، ومقاييس مُتقدّمة، وعمر بطارية طويل.</p>', 'ar'),
(342, 117, 'Garmin Forerunner 965', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Reloj con GPS para corredores y atletas. Ofrece VO2 máximo, métricas avanzadas y batería de larga duración.</p>', 'es'),
(343, 118, 'Fitbit Versa 4', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"674\" data-end=\"813\"><p data-start=\"677\" data-end=\"813\"><br data-start=\"695\" data-end=\"698\">\r\nAffordable and fitness-focused. Tracks heart rate, sleep, steps, and offers guided workouts with Fitbit Premium.</p>\r\n</li><p>\r\n</p><li data-start=\"815\" data-end=\"956\">\r\n<p data-start=\"818\" data-end=\"956\"></p></li>', 'en'),
(344, 118, 'فيتبيت فيرسا 4', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>سعر معقول ومُركز على اللياقة البدنية. يتتبع معدل ضربات القلب والنوم وعدد الخطوات، ويُقدم تمارين مُوجهة مع Fitbit Premium.</p>', 'ar'),
(345, 118, 'Fitbit Versa 4', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Asequible y enfocado en el fitness. Monitoriza la frecuencia cardíaca, el sueño y los pasos, y ofrece entrenamientos guiados con Fitbit Premium.</p>', 'es'),
(346, 119, 'Amazfit GTR 4', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><br data-start=\"835\" data-end=\"838\">\r\nStylish design with AMOLED display, built-in GPS, and long battery life. Great value for everyday fitness tracking.</p>', 'en'),
(347, 119, 'أمازفيت جي تي آر 4', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تصميم أنيق بشاشة AMOLED، ونظام تحديد المواقع العالمي (GPS) مدمج، وبطارية طويلة العمر. قيمة رائعة لمتابعة لياقتك البدنية اليومية.</p>', 'ar'),
(348, 119, 'Amazfit GTR 4', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Diseño elegante con pantalla AMOLED, GPS integrado y batería de larga duración. Excelente relación calidad-precio para el seguimiento diario de tu actividad física.</p>', 'es'),
(349, 120, 'Huawei Watch GT 4', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><br data-start=\"982\" data-end=\"985\">\r\nElegant design with accurate health monitoring, SpO2 tracking, and excellent battery performance</p>', 'en'),
(350, 120, 'ساعة هواوي GT 4', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تصميم أنيق مع مراقبة صحية دقيقة وتتبع SpO2 وأداء بطارية ممتاز</p>', 'ar'),
(351, 120, 'Huawei Watch GT 4', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Diseño elegante con monitoreo de salud preciso, seguimiento de SpO2 y excelente rendimiento de batería.</p>', 'es'),
(352, 121, 'TicWatch Pro 5', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"1087\" data-end=\"1220\"><p data-start=\"1090\" data-end=\"1220\"><br data-start=\"1108\" data-end=\"1111\">\r\nDual-screen smartwatch with Wear OS. Offers excellent battery life, Google apps support, and rugged build.</p>\r\n</li><p>\r\n</p><li data-start=\"1222\" data-end=\"1363\">\r\n<p data-start=\"1225\" data-end=\"1363\"></p></li>', 'en'),
(353, 121, 'ساعة تيك واتش برو 5', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>ساعة ذكية بشاشتين ونظام تشغيل Wear OS. تتميز بعمر بطارية ممتاز، ودعم تطبيقات جوجل، وهيكل متين.</p>', 'ar'),
(354, 121, 'TicWatch Pro 5', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Reloj inteligente de doble pantalla con Wear OS. Ofrece excelente duración de batería, compatibilidad con apps de Google y un diseño robusto.</p>', 'es'),
(355, 122, 'Apple MacBook Air M2', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">Ultra-slim, lightweight, and powerful with the Apple M2 chip. Ideal for students and professionals who value portability and battery life.</span>', 'en'),
(356, 122, 'أبل ماك بوك اير M2', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>نحيف للغاية، خفيف الوزن، وقوي بفضل شريحة Apple M2. مثالي للطلاب والمحترفين الذين يُقدّرون سهولة الحمل وعمر البطارية الطويل.</p>', 'ar'),
(357, 122, 'Apple MacBook Air M2', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Ultradelgado, ligero y potente con el chip M2 de Apple. Ideal para estudiantes y profesionales que valoran la portabilidad y la duración de la batería.</p>', 'es'),
(358, 123, 'Dell XPS 13', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">Premium ultrabook with a stunning InfinityEdge display, powerful Intel processors, and sleek aluminum design. Great for everyday productivity and travel.</span>', 'en'),
(359, 123, 'ديل XPS 13', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>جهاز Ultrabook فاخر بشاشة InfinityEdge مذهلة، ومعالجات Intel قوية، وتصميم أنيق من الألومنيوم. مثالي للإنتاجية اليومية والسفر.</p>', 'ar'),
(360, 123, 'Dell XPS 13', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Ultrabook premium con una impresionante pantalla InfinityEdge, potentes procesadores Intel y un elegante diseño de aluminio. Ideal para la productividad diaria y para viajar.</p>', 'es'),
(361, 124, 'HP Spectre x360', '{\"variant_name\":\"\",\"variant_options\":[]}', '<br><p>\r\n\r\n</p><ul data-start=\"521\" data-end=\"668\">\r\n<li data-start=\"521\" data-end=\"668\">\r\n<p data-start=\"523\" data-end=\"668\">A stylish 2-in-1 laptop with a 360° hinge, touchscreen, and long battery life. Suitable for creative professionals and students.</p>\r\n</li>\r\n</ul>', 'en'),
(362, 124, 'HP Spectre x360', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>كمبيوتر محمول أنيق 2 في 1، بمفصلة دوارة 360 درجة، وشاشة تعمل باللمس، وبطارية طويلة الأمد. مناسب للمحترفين المبدعين والطلاب.</p>', 'ar'),
(363, 124, 'HP Spectre x360', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una elegante laptop 2 en 1 con bisagra de 360°, pantalla táctil y batería de larga duración. Ideal para profesionales creativos y estudiantes.</p>', 'es'),
(364, 125, 'Lenovo ThinkPad X1 Carbon Gen 11', '{\"variant_name\":\"\",\"variant_options\":[]}', '<br><p>\r\n</p><ul data-start=\"714\" data-end=\"839\">\r\n<li data-start=\"714\" data-end=\"839\">\r\n<p data-start=\"716\" data-end=\"839\">Business-class laptop with legendary durability, best-in-class keyboard, and enterprise security features.</p></li></ul>', 'en'),
(365, 125, 'لينوفو ثينك باد X1 كاربون الجيل الحادي عشر', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>كمبيوتر محمول من فئة رجال الأعمال يتميز بمتانة أسطورية ولوحة مفاتيح هي الأفضل في فئتها وميزات أمان للمؤسسات.</p>', 'ar');
INSERT INTO `vendor_item_list_ln` (`id`, `item_id`, `title`, `variants`, `description`, `language`) VALUES
(366, 125, 'Lenovo ThinkPad X1 Carbon Gen 11', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Computadora portátil de clase empresarial con durabilidad legendaria, el mejor teclado de su clase y funciones de seguridad empresarial.</p>', 'es'),
(367, 126, 'Asus ROG Zephyrus G14', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">Compact and powerful gaming laptop with AMD Ryzen and NVIDIA RTX graphics. A great blend of performance and portability for gamers.</span>', 'en'),
(368, 126, 'أسوس ROG Zephyrus G14', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>كمبيوتر محمول قوي ومدمج للألعاب، مزود بمعالجي AMD Ryzen ورسومات NVIDIA RTX. مزيج رائع بين الأداء وسهولة الحمل لعشاق الألعاب.</p>', 'ar'),
(369, 126, 'Asus ROG Zephyrus G14', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Portátil gaming compacto y potente con procesadores AMD Ryzen y gráficos NVIDIA RTX. Una excelente combinación de rendimiento y portabilidad para gamers.</p>', 'es'),
(370, 127, 'Microsoft Surface Laptop 5', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">Sleek, minimalistic design with touchscreen support and premium build quality. Perfect for office work and everyday use.</span>', 'en'),
(371, 127, 'مايكروسوفت سيرفس لابتوب 5', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تصميم أنيق وبسيط، يدعم شاشة اللمس، وجودة تصنيع ممتازة. مثالي للعمل المكتبي والاستخدام اليومي.</p>', 'ar'),
(372, 127, 'Microsoft Surface Laptop 5', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Diseño elegante y minimalista con compatibilidad con pantalla táctil y calidad de construcción premium. Perfecto para la oficina y el uso diario.</p>', 'es'),
(373, 128, 'Acer Swift X', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">A budget-friendly laptop with dedicated GPU for content creators and casual gamers. Lightweight with solid performance.</span>', 'en'),
(374, 128, 'أيسر سويفت إكس', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>كمبيوتر محمول اقتصادي مزود بمعالج رسوميات مخصص لمنشئي المحتوى وهواة الألعاب. خفيف الوزن وأداء قوي.</p>', 'ar'),
(375, 128, 'Acer Swift X', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una laptop económica con GPU dedicada para creadores de contenido y jugadores ocasionales. Ligera y con un rendimiento sólido.</p>', 'es'),
(376, 129, 'Samsung Galaxy Book3 Pro 360', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\"> A 2-in-1 touchscreen laptop with AMOLED display, great for entertainment, drawing, and business use.</span>', 'en'),
(377, 129, 'سامسونج جالاكسي بوك 3 برو 360', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>كمبيوتر محمول 2 في 1 مزود بشاشة تعمل باللمس AMOLED، مثالي للترفيه والرسم واستخدام الأعمال.</p>', 'ar'),
(378, 129, 'Samsung Galaxy Book3 Pro 360', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una computadora portátil con pantalla táctil 2 en 1 con pantalla AMOLED, ideal para entretenimiento, dibujo y uso comercial.</p>', 'es'),
(379, 130, 'Dell XPS Desktop', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"70\" data-end=\"215\"><p data-start=\"73\" data-end=\"215\"><br data-start=\"93\" data-end=\"96\">\r\nA high-performance desktop with Intel Core processors, ideal for creators and professionals needing power and speed.</p>\r\n</li><p>\r\n</p><li data-start=\"217\" data-end=\"359\">\r\n<p data-start=\"220\" data-end=\"359\"></p></li>', 'en'),
(380, 130, 'كمبيوتر سطح المكتب Dell XPS', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>جهاز كمبيوتر مكتبي عالي الأداء مزود بمعالجات Intel Core، مثالي للمبدعين والمحترفين الذين يحتاجون إلى القوة والسرعة.</p>', 'ar'),
(381, 130, 'Computadora de escritorio Dell XPS', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una computadora de escritorio de alto rendimiento con procesadores Intel Core, ideal para creadores y profesionales que necesitan potencia y velocidad.</p>', 'es'),
(382, 131, 'HP Pavilion Desktop', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"217\" data-end=\"359\"><p data-start=\"220\" data-end=\"359\"><br data-start=\"243\" data-end=\"246\">\r\nA reliable mid-range PC for everyday use, offering good performance for work, entertainment, and light gaming.</p>\r\n</li><p>\r\n</p><li data-start=\"361\" data-end=\"516\">\r\n<p data-start=\"364\" data-end=\"516\"></p></li>', 'en'),
(383, 131, 'كمبيوتر HP Pavilion المكتبي', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>جهاز كمبيوتر شخصي متوسط ​​المدى موثوق به للاستخدام اليومي، يوفر أداءً جيدًا للعمل والترفيه والألعاب الخفيفة.</p>', 'ar'),
(384, 131, 'Computadora de escritorio HP Pavilion', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una PC de gama media confiable para uso diario, que ofrece un buen rendimiento para el trabajo, el entretenimiento y los juegos ligeros.</p>', 'es'),
(385, 132, 'Apple iMac (24-inch, M3 Chip)', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><br data-start=\"397\" data-end=\"400\">\r\nSleek all-in-one design with stunning Retina display, powered by Apple’s M3 chip for seamless creative workflows.</p>', 'en'),
(386, 132, 'Apple iMac (24 بوصة، شريحة M3)', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تصميم أنيق متكامل مع شاشة Retina مذهلة، مدعوم بشريحة M3 من Apple لتحقيق تدفقات عمل إبداعية سلسة.</p>', 'ar'),
(387, 132, 'Apple iMac (24 pulgadas, chip M3)', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Elegante diseño todo en uno con una impresionante pantalla Retina y el chip M3 de Apple para flujos de trabajo creativos perfectos.</p>', 'es'),
(388, 133, 'Lenovo ThinkCentre M Series', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"518\" data-end=\"653\"><p data-start=\"521\" data-end=\"653\"><br data-start=\"552\" data-end=\"555\">\r\nBusiness-class desktops known for durability, security, and performance in office environments.</p>\r\n</li><p>\r\n</p><li data-start=\"655\" data-end=\"786\">\r\n<p data-start=\"658\" data-end=\"786\"></p></li>', 'en'),
(389, 133, 'سلسلة لينوفو ثينك سنتر M', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>أجهزة كمبيوتر مكتبية من فئة الأعمال معروفة بمتانتها وأمانها وأدائها في بيئات المكاتب.</p>', 'ar'),
(390, 133, 'Lenovo ThinkCentre Serie M', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Computadoras de escritorio de clase empresarial conocidas por su durabilidad, seguridad y rendimiento en entornos de oficina.</p>', 'es'),
(391, 134, 'Acer Aspire TC Series', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"655\" data-end=\"786\"><p data-start=\"658\" data-end=\"786\"><br data-start=\"683\" data-end=\"686\">\r\nBudget-friendly desktop with solid performance for home users, students, and casual multitasking.</p>\r\n</li><p>\r\n</p><li data-start=\"788\" data-end=\"942\">\r\n<p data-start=\"791\" data-end=\"942\"></p></li>', 'en'),
(392, 134, 'سلسلة Acer Aspire TC', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>كمبيوتر مكتبي صديق للميزانية مع أداء قوي لمستخدمي المنازل والطلاب ومتعددي المهام غير الرسميين.</p>', 'ar'),
(393, 134, 'Serie TC de Acer Aspire', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Computadora de escritorio económica con un rendimiento sólido para usuarios domésticos, estudiantes y personas que realizan múltiples tareas de manera casual.</p>', 'es'),
(394, 135, 'Dell UltraSharp U2723QE', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">A 27-inch 4K IPS monitor with exceptional color accuracy and USB-C connectivity. Ideal for professionals who need high-resolution and color precision for design or editing.</span>', 'en'),
(395, 135, 'ديل ألترا شارب U2723QE', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>شاشة IPS بدقة 4K مقاس 27 بوصة، تتميز بدقة ألوان استثنائية، ومنفذ USB-C. مثالية للمحترفين الذين يحتاجون إلى دقة ألوان عالية للتصميم أو التحرير.</p>', 'ar'),
(396, 135, 'Dell UltraSharp U2723QE', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Monitor IPS 4K de 27 pulgadas con una precisión de color excepcional y conectividad USB-C. Ideal para profesionales que necesitan alta resolución y precisión de color para diseño o edición.</p>', 'es'),
(397, 136, 'LG UltraGear 27GN950-B', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">A 27-inch 4K Nano IPS gaming monitor with 144Hz refresh rate and 1ms response time. Great for high-end PC gaming with both speed and visual fidelity.</span>', 'en'),
(398, 136, 'إل جي ألترا جير 27GN950-B', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>شاشة ألعاب Nano IPS بدقة 4K مقاس 27 بوصة، بمعدل تحديث 144 هرتز وزمن استجابة 1 مللي ثانية. مثالية لألعاب الكمبيوتر عالية الأداء، مع سرعة ودقة بصرية عالية.</p>', 'ar'),
(399, 136, 'LG UltraGear 27GN950-B', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Monitor para juegos Nano IPS 4K de 27 pulgadas con frecuencia de actualización de 144 Hz y un tiempo de respuesta de 1 ms. Ideal para juegos de PC de alta gama con velocidad y fidelidad visual.</p>', 'es'),
(400, 137, 'ASUS ProArt Display PA278CV', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\"> A 27-inch WQHD monitor designed for creatives, offering factory-calibrated color accuracy and a wide color gamut (100% sRGB and Rec.709).</span>', 'en'),
(401, 137, 'شاشة ASUS ProArt PA278CV', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>شاشة WQHD مقاس 27 بوصة مصممة للمبدعين، حيث توفر دقة ألوان معايرة في المصنع ومجموعة واسعة من الألوان (100% sRGB وRec.709).</p>', 'ar'),
(402, 137, 'Pantalla ASUS ProArt PA278CV', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Un monitor WQHD de 27 pulgadas diseñado para creativos, que ofrece precisión de color calibrada de fábrica y una amplia gama de colores (100 % sRGB y Rec.709).</p>', 'es'),
(403, 138, 'Samsung Odyssey Neo G9', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\"> A 49-inch curved ultrawide gaming monitor with a 240Hz refresh rate, mini-LED panel, and HDR2000 support. Immersive experience for gaming and multitasking.</span>', 'en'),
(404, 138, 'سامسونج أوديسي نيو جي 9', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>شاشة ألعاب منحنية فائقة الاتساع مقاس 49 بوصة، بمعدل تحديث 240 هرتز، ولوحة Mini-LED، ودعم HDR2000. تجربة غامرة للألعاب وتعدد المهام.</p>', 'ar'),
(405, 138, 'Samsung Odyssey Neo G9', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Monitor curvo ultraancho para juegos de 49 pulgadas con frecuencia de actualización de 240 Hz, panel mini-LED y compatibilidad con HDR2000. Experiencia inmersiva para juegos y multitarea.</p>', 'es'),
(406, 139, 'Apple Studio Display', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">A 27-inch 5K Retina display with P3 wide color and True Tone. Designed for Mac users, it offers excellent integration and visual clarity for creative professionals.</span>', 'en'),
(407, 139, 'شاشة Apple Studio', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>شاشة Retina مقاس 27 بوصة بدقة 5K وألوان P3 واسعة وتقنية True Tone. صُممت لمستخدمي أجهزة Mac، وتوفر تكاملاً ممتازًا ووضوحًا بصريًا مثاليًا للمحترفين المبدعين.</p>', 'ar'),
(408, 139, 'Pantalla de estudio de Apple', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Pantalla Retina 5K de 27 pulgadas con gama cromática P3 y True Tone. Diseñada para usuarios de Mac, ofrece excelente integración y claridad visual para profesionales creativos.</p>', 'es'),
(409, 140, 'Mechanical Keyboard', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><br data-start=\"88\" data-end=\"91\">\r\nUses individual mechanical switches under each key, offering tactile feedback and durability. Popular with gamers and typists.</p>', 'en'),
(410, 140, 'لوحة المفاتيح الميكانيكية', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>يستخدم مفاتيح ميكانيكية فردية أسفل كل مفتاح، مما يوفر استجابة لمسية ومتانة. شائع بين اللاعبين والكتاب.</p>', 'ar'),
(411, 140, 'Teclado mecánico', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Utiliza interruptores mecánicos individuales bajo cada tecla, lo que ofrece respuesta táctil y durabilidad. Popular entre jugadores y mecanógrafos.</p>', 'es'),
(412, 141, 'Membrane Keyboard', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"222\" data-end=\"372\"><p data-start=\"225\" data-end=\"372\"><br data-start=\"246\" data-end=\"249\">\r\nUses pressure pads with printed circuits. Quieter and more affordable but less tactile compared to mechanical keyboards.</p>\r\n</li><p>\r\n</p><li data-start=\"374\" data-end=\"519\">\r\n<p data-start=\"377\" data-end=\"519\"></p></li>', 'en'),
(413, 141, 'لوحة مفاتيح غشائية', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>يستخدم وسادات ضغط مزودة بدوائر مطبوعة. أكثر هدوءًا وأقل تكلفة، ولكنه أقل حساسيةً مقارنةً بلوحات المفاتيح الميكانيكية.</p>', 'ar'),
(414, 141, 'Teclado de membrana', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Utiliza almohadillas de presión con circuitos impresos. Más silencioso y económico, pero menos táctil que los teclados mecánicos.</p>', 'es'),
(415, 142, 'Wireless Keyboard', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"374\" data-end=\"519\"><p data-start=\"377\" data-end=\"519\">Connects via Bluetooth or a USB receiver, offering cable-free convenience. Ideal for minimalistic or mobile setups.</p>\r\n</li><p>\r\n</p><li data-start=\"521\" data-end=\"648\">\r\n<p data-start=\"524\" data-end=\"648\"></p></li>', 'en'),
(416, 142, 'لوحة مفاتيح لاسلكية', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>يتصل عبر البلوتوث أو مستقبل USB، مما يوفر راحة فائقة بدون كابلات. مثالي للإعدادات البسيطة أو المتنقلة.</p>', 'ar'),
(417, 142, 'Teclado inalámbrico', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Se conecta por Bluetooth o un receptor USB, lo que ofrece comodidad sin cables. Ideal para configuraciones minimalistas o móviles.</p>', 'es'),
(418, 143, 'Gaming Keyboard', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"521\" data-end=\"648\"><p data-start=\"524\" data-end=\"648\">Designed for gamers with features like RGB lighting, programmable keys, and fast response switches.</p>\r\n</li><p>\r\n</p><li data-start=\"650\" data-end=\"792\">\r\n<p data-start=\"653\" data-end=\"792\"></p></li>', 'en'),
(419, 143, 'لوحة مفاتيح الألعاب', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تم تصميمه خصيصًا للاعبي الألعاب مع ميزات مثل إضاءة RGB والمفاتيح القابلة للبرمجة ومفاتيح الاستجابة السريعة.</p>', 'ar'),
(420, 143, 'Teclado para juegos', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Diseñado para jugadores con características como iluminación RGB, teclas programables e interruptores de respuesta rápida.</p>', 'es'),
(421, 144, 'Ergonomic Keyboard', '{\"variant_name\":\"\",\"variant_options\":[]}', '<li data-start=\"650\" data-end=\"792\"><p data-start=\"653\" data-end=\"792\"><br data-start=\"675\" data-end=\"678\">\r\nShaped to reduce strain on hands and wrists. Often split or curved, used to prevent repetitive strain injuries.</p>\r\n</li><p>\r\n</p><li data-start=\"794\" data-end=\"934\">\r\n<p data-start=\"797\" data-end=\"934\"></p></li>', 'en'),
(422, 144, 'لوحة مفاتيح مريحة', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>مصممة لتقليل إجهاد اليدين والمعصمين. غالبًا ما تكون مشقوقة أو منحنية، وتُستخدم لمنع إصابات الإجهاد المتكررة.</p>', 'ar'),
(423, 144, 'Teclado ergonómico', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Diseñado para reducir la tensión en manos y muñecas. Suele estar partido o curvado, y se utiliza para prevenir lesiones por esfuerzo repetitivo.</p>', 'es'),
(424, 145, 'Virtual Keyboard', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>\r\n<p data-start=\"936\" data-end=\"985\" data-is-last-node=\"\" data-is-only-node=\"\"></p></p><ol data-start=\"62\" data-end=\"934\"><li data-start=\"794\" data-end=\"934\"><p data-start=\"797\" data-end=\"934\"><br data-start=\"817\" data-end=\"820\">\r\nA software-based keyboard displayed on screens (like on smartphones or tablets). Tapped directly on the screen.</p>\r\n</li>\r\n</ol>', 'en'),
(425, 145, 'لوحة المفاتيح الافتراضية', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>لوحة مفاتيح برمجية تُعرض على الشاشات (مثل الهواتف الذكية والأجهزة اللوحية). تُنقر عليها مباشرةً.</p>', 'ar'),
(426, 145, 'Teclado virtual', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Un teclado basado en software que se muestra en pantallas (como en smartphones o tablets). Se pulsa directamente en la pantalla.</p>', 'es'),
(427, 146, 'Notice Xtrike Me GW-116 Wireless Mouse', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">The Xtrike Me </span><strong style=\"margin: 0px; padding: 0px; color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">GW-116</strong><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\"> Wireless </span><a href=\"https://www.startech.com.bd/accessories/mouse\" target=\"\" style=\"margin: 0px; padding: 0px; text-decoration-line: underline; background-color: rgb(255, 255, 255); color: rgb(0, 0, 0); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px;\">Mouse </a><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">has a basic but functional design, making it a perfect choice for individuals who value the comfort and convenience of use in their daily computing activities. It offers a simple and easy-to-use interface with three buttons, making sure that all the features you need are close at hand. The mouse\'s optical sensor allows for precise and seamless tracking on a range of surfaces, making it dependable for usage in both home and workplace settings. </span></p>', 'en'),
(428, 146, 'إشعار ماوس لاسلكي Xtrike Me GW-116', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>يتميز ماوس Xtrike Me GW-116 اللاسلكي بتصميم بسيط وعملي، مما يجعله خيارًا مثاليًا لمن يُقدّرون الراحة وسهولة الاستخدام في أنشطة الحوسبة اليومية. يوفر واجهة استخدام بسيطة وسهلة بثلاثة أزرار، مما يضمن سهولة الوصول إلى جميع الميزات التي تحتاجها. يتيح المستشعر البصري للفأرة تتبعًا دقيقًا وسلسًا على مجموعة متنوعة من الأسطح، مما يجعله مناسبًا للاستخدام في المنزل ومكان العمل.</p>', 'ar'),
(429, 146, 'Aviso Ratón inalámbrico Xtrike Me GW-116', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El ratón inalámbrico Xtrike Me GW-116 tiene un diseño básico pero funcional, lo que lo convierte en la opción perfecta para quienes valoran la comodidad y la practicidad en sus actividades informáticas diarias. Ofrece una interfaz sencilla y fácil de usar con tres botones, lo que garantiza que todas las funciones que necesita estén a mano. El sensor óptico del ratón permite un seguimiento preciso y fluido en diversas superficies, lo que lo hace fiable tanto para el hogar como para el trabajo.</p>', 'es'),
(430, 147, 'Razer Basilisk V3 X HyperSpeed', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">The Razer </span><strong style=\"margin: 0px; padding: 0px; color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">Basilisk V3 X HyperSpeed</strong><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\"> RGB Wireless Gaming </span><a href=\"https://www.startech.com.bd/accessories/mouse\" target=\"\" style=\"margin: 0px; padding: 0px; text-decoration-line: underline; background-color: rgb(255, 255, 255); color: rgb(0, 0, 0); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px;\">Mouse </a><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">combines an iconic ergonomic design with high-performance features, making it an excellent choice for gamers who value precision and customization.</span></p>', 'en'),
(431, 147, 'Razer Basilisk V3 X HyperSpeed', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>يجمع ماوس الألعاب اللاسلكي Razer Basilisk V3 X HyperSpeed ​​RGB بين التصميم المريح المميز والميزات عالية الأداء، مما يجعله خيارًا ممتازًا للاعبين الذين يقدرون الدقة والتخصيص.</p>', 'ar'),
(432, 147, 'Razer Basilisk V3 X HyperSpeed', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El mouse inalámbrico para juegos Razer Basilisk V3 X HyperSpeed ​​RGB combina un diseño ergonómico icónico con características de alto rendimiento, lo que lo convierte en una excelente opción para los jugadores que valoran la precisión y la personalización.</p>', 'es'),
(433, 148, 'Asus WT425 Optical Wireless Mouse', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; text-align: justify; background-color: rgb(255, 255, 255);\">Asus WT425 Optical Wireless Mouse comes with Simple design that works with every PC in total plug and play every time. This mouse features advanced tracking technology with resolutions up to 1600DPI. A dedicated switch lets you easily select sensitivity levels of 1000 and 1600DPI; while its silent mouse click design means you can use it in quiet environments. </span></p>', 'en'),
(434, 148, 'ماوس لاسلكي بصري Asus WT425', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>ماوس آسوس WT425 البصري اللاسلكي يتميز بتصميم بسيط يتوافق مع جميع أجهزة الكمبيوتر، يعمل فورًا. يتميز بتقنية تتبع متقدمة بدقة تصل إلى 1600 نقطة في البوصة. يتيح لك مفتاح مخصص اختيار مستويات الحساسية بسهولة بين 1000 و1600 نقطة في البوصة، بينما يتيح لك تصميمه الصامت استخدام الماوس في البيئات الهادئة.</p>', 'ar'),
(435, 148, 'Ratón óptico inalámbrico Asus WT425', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El ratón óptico inalámbrico Asus WT425 presenta un diseño sencillo que lo hace compatible con cualquier PC, con total comodidad. Este ratón incorpora tecnología de seguimiento avanzada con resoluciones de hasta 1600 DPI. Un interruptor dedicado permite seleccionar fácilmente los niveles de sensibilidad de 1000 y 1600 DPI; además, su diseño de clic silencioso permite usarlo en entornos silenciosos.</p>', 'es'),
(436, 149, 'Apple Magic Mouse', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; text-align: justify; background-color: rgb(255, 255, 255);\">The Apple Magic Mouse is a wireless and rechargeable mouse for Bluetooth-enabled Mac with OS X 10.11 or later and iPad with iPadOS 13.4 or later. It comes with an optimized foot design that lets it glide smoothly across your desk.</span></p>', 'en'),
(437, 149, 'ماوس أبل ماجيك', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>ماوس Apple Magic Mouse لاسلكي وقابل لإعادة الشحن، وهو مناسب لأجهزة Mac المزودة بتقنية Bluetooth بنظام OS X 10.11 أو أحدث، وأجهزة iPad المزودة بنظام iPadOS 13.4 أو أحدث. يأتي بتصميم قاعدة مُحسّن يتيح له الانزلاق بسلاسة على مكتبك.</p>', 'ar'),
(438, 149, 'Ratón mágico de Apple', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El Apple Magic Mouse es un ratón inalámbrico y recargable para Mac con Bluetooth y OS X 10.11 o posterior, y iPad con iPadOS 13.4 o posterior. Cuenta con un diseño de base optimizado que permite un deslizamiento suave sobre el escritorio.</p>', 'es'),
(439, 150, 'Xiaomi WSB01TM', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p><span style=\"color: rgb(1, 19, 45); font-family: \"Trebuchet MS\", sans-serif; font-size: 15px; background-color: rgb(255, 255, 255);\">Star Tech brings a very lightweight 82g portable USB mouse for you. This 1200dpi resolution mouse has fast scrolling and smooth gliding on any surfaces you prefer. Its 2.4Ghigh-speed transmission covers a distance of 10 m. It has 4-button including a â€œbackâ€� key compatible with windows OS. </span></p>', 'en'),
(440, 150, 'شاومي WSB01TM', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تقدم لك ستار تك ماوس USB محمول وخفيف الوزن للغاية، وزنه 82 غرامًا. يتميز هذا الماوس بدقة 1200 نقطة في البوصة، وسرعة تمرير وانزلاق سلس على أي سطح تفضله. يغطي نقله عالي السرعة 2.4 جيجاهرتز مسافة 10 أمتار. مزود بأربعة أزرار، بما في ذلك زر الرجوع، ومتوافق مع نظام تشغيل ويندوز.</p>', 'ar'),
(441, 150, 'Xiaomi WSB01TM', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Star Tech te trae un ratón USB portátil muy ligero de 82 g. Este ratón con una resolución de 1200 dpi ofrece un desplazamiento rápido y un deslizamiento suave en cualquier superficie. Su transmisión de alta velocidad de 2,4 G cubre una distancia de 10 m. Cuenta con 4 botones, incluyendo una tecla de retroceso, compatible con Windows.</p>', 'es'),
(442, 151, 'Sony WH-1000XM5', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p data-start=\"195\" data-end=\"423\">Top-tier noise-canceling headphones with exceptional sound quality, 30+ hours of battery life, and a sleek design. Perfect for travelers and audiophiles alike.</p>', 'en'),
(443, 151, 'سوني WH-1000XM5', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>سماعات رأس فاخرة بخاصية إلغاء الضوضاء، بجودة صوت استثنائية، وعمر بطارية يدوم لأكثر من 30 ساعة، وتصميم أنيق. مثالية للمسافرين وعشاق الموسيقى على حد سواء.</p>', 'ar'),
(444, 151, 'Sony WH-1000XM5', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Audífonos con cancelación de ruido de alta gama con una calidad de sonido excepcional, más de 30 horas de duración de batería y un diseño elegante. Perfectos tanto para viajeros como para audiófilos.</p>', 'es'),
(445, 152, 'apple headphones', '{\"variant_name\":\"\",\"variant_options\":[]}', '<br><p data-start=\"471\" data-end=\"690\">\r\nCompact and powerful, these earbuds offer active noise cancellation, spatial audio, and seamless integration with Apple devices. Great for everyday use.</p>', 'en'),
(446, 152, 'سماعات ابل', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تتميز هذه السماعات الصغيرة والفعّالة بإلغاء الضوضاء النشط، وصوت محيطي، وتكامل سلس مع أجهزة Apple. مثالية للاستخدام اليومي.</p>', 'ar'),
(447, 152, 'auriculares de Apple', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Compactos y potentes, estos auriculares ofrecen cancelación activa de ruido, audio espacial y una integración perfecta con dispositivos Apple. Ideales para el día a día.</p>', 'es'),
(448, 153, 'Bose QuietComfort 45', '{\"variant_name\":\"\",\"variant_options\":[]}', '<br><p data-start=\"731\" data-end=\"938\">\r\nKnown for unmatched comfort and clear, balanced sound. Active noise cancellation is strong, making them ideal for flights, work, or study.</p>', 'en'),
(449, 153, 'بوس كوايت كومفورت 45', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تشتهر براحة لا مثيل لها وصوت نقي ومتوازن. تتميز بخاصية إلغاء الضوضاء النشطة، مما يجعلها مثالية للرحلات الجوية أو العمل أو الدراسة.</p>', 'ar'),
(450, 153, 'Bose QuietComfort 45', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Conocidos por su comodidad inigualable y un sonido nítido y equilibrado. Su potente cancelación activa de ruido los hace ideales para vuelos, trabajo o estudios.</p>', 'es'),
(451, 154, 'Sennheiser Momentum 4 Wireless', '{\"variant_name\":\"\",\"variant_options\":[]}', '<br><p data-start=\"989\" data-end=\"1197\">\r\nDelivers crystal-clear sound with punchy bass and a massive 60-hour battery life. Premium build and stylish design for those who want both function and form.</p>', 'en'),
(452, 154, 'سماعات سينهايزر مومنتوم 4 اللاسلكية', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>يُقدّم صوتًا فائق الوضوح مع جهير قوي وعمر بطارية طويل يصل إلى 60 ساعة. تصميم فاخر وأنيق لمن يبحثون عن الأداء والشكل الأنيق.</p>', 'ar'),
(453, 154, 'Auriculares inalámbricos Sennheiser Momentum 4', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Ofrece un sonido nítido con graves potentes y una batería de 60 horas de duración. Construcción premium y diseño elegante para quienes buscan funcionalidad y estilo.</p>', 'es'),
(454, 155, 'Apple AirPods Pro (2nd Gen)', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">Premium wireless earbuds with active noise cancellation, Adaptive Transparency, and personalized spatial audio. Seamless integration with Apple devices and a long battery life. Great for iPhone users.</span>', 'en'),
(455, 155, 'سماعات ابل ايربودز برو', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>سماعات أذن لاسلكية فاخرة مزودة بخاصية إلغاء الضوضاء النشط، وشفافية تكيفية، وصوت مكاني مخصص. تكامل سلس مع أجهزة Apple وعمر بطارية طويل. مثالية لمستخدمي iPhone.</p>', 'ar'),
(456, 155, 'AirPods Pro de Apple', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Auriculares inalámbricos premium con cancelación activa de ruido, Transparencia Adaptativa y audio espacial personalizado. Integración perfecta con dispositivos Apple y batería de larga duración. Ideales para usuarios de iPhone.</p>', 'es'),
(457, 156, 'Sony WF-1000XM5', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">Top-tier sound quality with industry-leading noise cancellation. Features LDAC support, adaptive sound control, and up to 24 hours of battery life with the case. Best for audiophiles and frequent travelers.</span>', 'en'),
(458, 156, 'سوني WF-1000XM5', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>جودة صوت فائقة مع تقنية إلغاء ضوضاء رائدة في هذا المجال. تتميز بدعم LDAC، وتحكم تكيفي في الصوت، وعمر بطارية يصل إلى 24 ساعة مع الحافظة. مثالية لعشاق الموسيقى ومحبي السفر الدائم.</p>', 'ar'),
(459, 156, 'Sony WF-1000XM5', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Calidad de sonido superior con cancelación de ruido líder en la industria. Compatible con LDAC, control de sonido adaptativo y hasta 24 horas de duración de batería con estuche. Ideal para audiófilos y viajeros frecuentes.</p>', 'es'),
(460, 157, 'Samsung Galaxy Buds2 Pro', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">Compact, lightweight earbuds with rich 24-bit Hi-Fi sound, ANC, and IPX7 water resistance. Works best with Samsung Galaxy devices but compatible with others too.</span>', 'en'),
(461, 157, 'سماعات سامسونج جالكسي بودز 2 برو', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>سماعات أذن صغيرة الحجم وخفيفة الوزن، تتميز بصوت هاي فاي غني بدقة ٢٤ بت، وخاصية إلغاء الضوضاء النشطة، ومقاومة للماء بتصنيف IPX7. تعمل بشكل مثالي مع أجهزة سامسونج جالاكسي، ولكنها متوافقة أيضًا مع غيرها.</p>', 'ar'),
(462, 157, 'Samsung Galaxy Buds 2 Pro', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Audífonos compactos y ligeros con sonido Hi-Fi de 24 bits, cancelación de ruido activa (ANC) y resistencia al agua IPX7. Funcionan mejor con dispositivos Samsung Galaxy, pero también son compatibles con otros.</p>', 'es'),
(463, 158, 'Jabra Elite 7 Pro', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">Durable, ergonomic design with advanced voice pickup via bone conduction sensors. Great for calls, workouts, and long listening sessions. Features adjustable ANC and long battery life.</span>', 'en'),
(464, 158, 'جابرا إيليت 7 برو', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تصميم متين ومريح مع تقنية التقاط صوت متقدمة عبر مستشعرات التوصيل العظمي. مثالية للمكالمات والتمارين الرياضية وجلسات الاستماع الطويلة. تتميز بخاصية إلغاء الضوضاء النشطة القابلة للتعديل وعمر بطارية طويل.</p>', 'ar'),
(465, 158, 'Jabra Elite 7 Pro', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Diseño ergonómico y duradero con captación de voz avanzada mediante sensores de conducción ósea. Ideales para llamadas, entrenamientos y largas sesiones de escucha. Cuentan con cancelación activa de ruido (ANC) ajustable y batería de larga duración.</p>', 'es'),
(466, 159, 'Bose QuietComfort Earbuds', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">Known for powerful active noise cancellation and clear, deep sound. Comfortable fit and customizable sound profiles. Ideal for those who prioritize noise cancellation and sound clarity.</span>', 'en'),
(467, 159, 'سماعات Bose QuietComfort', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تشتهر بتقنية إلغاء الضوضاء النشطة القوية وصوت نقي وعميق. تصميم مريح وأنماط صوت قابلة للتخصيص. مثالية لمن يُعطون الأولوية لإلغاء الضوضاء ونقاء الصوت.</p>', 'ar'),
(468, 159, 'Auriculares Bose QuietComfort', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Conocidos por su potente cancelación activa de ruido y un sonido nítido y profundo. Ajuste cómodo y perfiles de sonido personalizables. Ideales para quienes priorizan la cancelación de ruido y la claridad del sonido.</p>', 'es'),
(469, 160, 'Nothing Ear', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">Stylish and affordable earbuds with a transparent design and solid ANC. Delivers balanced sound, fast pairing, and a unique aesthetic. Great choice for budget-conscious users seeking premium features.</span>', 'en'),
(470, 160, 'لا شيء أذن', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>سماعات أذن أنيقة وبأسعار معقولة بتصميم شفاف وعزل فعال للضوضاء. توفر صوتًا متوازنًا، واقترانًا سريعًا، وتصميمًا فريدًا. خيار رائع للمستخدمين ذوي الميزانية المحدودة الذين يبحثون عن ميزات متميزة.</p>', 'ar'),
(471, 160, 'Nada oído', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Audífonos elegantes y económicos con diseño transparente y excelente cancelación de ruido activa (ANC). Ofrecen un sonido equilibrado, un emparejamiento rápido y una estética única. Ideal para usuarios con presupuesto ajustado que buscan funciones premium.</p>', 'es'),
(472, 161, 'Samsung QN90C Neo QLED 4K Smart TV', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\"> This premium 4K TV features Mini LED backlighting for ultra-bright HDR, rich contrast, and excellent color accuracy. It\'s ideal for both watching movies and high-performance gaming with features like low input lag and HDMI 2.1 support.</span>', 'en'),
(473, 161, 'تلفزيون سامسونج QN90C نيو كيو ال اي دي 4K الذكي', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>يتميز هذا التلفزيون الفاخر بدقة 4K بإضاءة خلفية Mini LED لتوفير HDR فائق السطوع، وتباين غني، ودقة ألوان ممتازة. إنه مثالي لمشاهدة الأفلام والألعاب عالية الأداء، بفضل ميزات مثل انخفاض تأخر الإدخال ودعم HDMI 2.1.</p>', 'ar'),
(474, 161, 'Televisor Samsung QN90C Neo QLED 4K', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Este televisor 4K premium cuenta con retroiluminación Mini LED para un HDR ultrabrillante, un contraste intenso y una excelente precisión de color. Es ideal tanto para ver películas como para jugar videojuegos de alto rendimiento, con características como bajo retardo de entrada y compatibilidad con HDMI 2.1.</p>', 'es'),
(475, 162, 'LG C3 OLED Evo', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">One of the top OLED TVs available, the LG C3 offers perfect blacks, infinite contrast, and vibrant colors. It\'s a favorite among cinephiles and gamers alike, with support for Dolby Vision, G-Sync, and HDMI 2.1.</span>', 'en'),
(476, 162, 'إل جي C3 OLED Evo', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>يُعدّ تلفزيون LG C3 من أفضل تلفزيونات OLED المتوفرة، حيث يُقدّم لونًا أسودًا مثاليًا، وتباينًا لا نهائيًا، وألوانًا نابضة بالحياة. وهو الخيار المُفضّل لدى مُحبي السينما والألعاب على حدٍ سواء، بفضل دعمه لتقنيات Dolby Vision وG-Sync وHDMI 2.1.</p>', 'ar'),
(477, 162, 'LG C3 OLED Evo', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>El LG C3, uno de los mejores televisores OLED del mercado, ofrece negros perfectos, contraste infinito y colores vibrantes. Es uno de los favoritos tanto de cinéfilos como de gamers, gracias a su compatibilidad con Dolby Vision, G-Sync y HDMI 2.1.</p>', 'es'),
(478, 163, 'Sony Bravia XR A80L OLED', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">Known for its cinematic picture quality and superb upscaling, the Sony A80L combines OLED display tech with the Cognitive Processor XR to deliver realistic visuals and impressive motion handling.</span>', 'en'),
(479, 163, 'سوني برافيا XR A80L OLED', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تشتهر Sony A80L بجودة صورها السينمائية وقدرتها الرائعة على تحسين الجودة، حيث تجمع بين تقنية شاشة OLED والمعالج المعرفي XR لتقديم صور واقعية ومعالجة حركة مثيرة للإعجاب.</p>', 'ar'),
(480, 163, 'Sony Bravia XR A80L OLED', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Conocida por su calidad de imagen cinematográfica y su excelente escalamiento, la Sony A80L combina la tecnología de pantalla OLED con el procesador cognitivo XR para ofrecer imágenes realistas y un manejo del movimiento impresionante.</p>', 'es'),
(481, 164, 'TCL 6-Series (R655) QLED', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">A great mid-range option, this QLED TV offers Mini-LED technology, Dolby Vision, and excellent gaming features at a more affordable price. It\'s often praised for its balance between performance and value.</span>', 'en'),
(482, 164, 'تلفزيون TCL QLED من السلسلة 6 (R655)', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>خيار رائع من الفئة المتوسطة، يوفر تلفزيون QLED هذا تقنية Mini-LED، وتقنية Dolby Vision، وميزات ألعاب ممتازة بسعر مناسب. ويُشاد به كثيرًا لتوازنه بين الأداء والقيمة.</p>', 'ar'),
(483, 164, 'TCL Serie 6 (R655) QLED', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Una excelente opción de gama media, este televisor QLED ofrece tecnología Mini-LED, Dolby Vision y excelentes funciones de juego a un precio más asequible. Recibe elogios por su excelente relación calidad-precio.</p>', 'es'),
(484, 165, 'Hisense U8K ULED 4K TV', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">This TV delivers surprisingly high-end features for its price, including Quantum Dot color, Mini LED backlighting, and up to 1500 nits of brightness. Great for bright rooms and action-packed content.</span>', 'en'),
(485, 165, 'تلفزيون Hisense U8K ULED 4K', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>يقدم هذا التلفزيون ميزات فائقة الجودة بشكل مدهش مقارنةً بسعره، بما في ذلك ألوان Quantum Dot، وإضاءة خلفية Mini LED، وسطوع يصل إلى 1500 شمعة. مثالي للغرف المضيئة والمحتوى المليء بالحركة.</p>', 'ar'),
(486, 165, 'Televisor Hisense U8K ULED 4K', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Este televisor ofrece características sorprendentemente avanzadas para su precio, como color Quantum Dot, retroiluminación Mini LED y hasta 1500 nits de brillo. Ideal para habitaciones iluminadas y contenido de acción.</p>', 'es'),
(487, 166, 'Vizio MQX-Series 4K QLED', '{\"variant_name\":\"\",\"variant_options\":[]}', '<span style=\"font-size: 1rem;\">A budget-friendly QLED TV with full-array local dimming, HDR support, and strong gaming performance (120Hz refresh rate). Ideal for shoppers looking for value without sacrificing too much picture quality.</span>', 'en'),
(488, 166, 'تلفزيونات Vizio MQX-Series 4K QLED', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>تلفزيون QLED اقتصادي مع تعتيم محلي كامل النطاق، ودعم HDR، وأداء ألعاب قوي (معدل تحديث ١٢٠ هرتز). مثالي للمتسوقين الباحثين عن قيمة عالية دون التضحية بجودة الصورة.</p>', 'ar'),
(489, 166, 'Vizio Serie MQX 4K QLED', '{\"variant_name\":\"\",\"variant_options\":[]}', '<p>Un televisor QLED económico con atenuación local de matriz completa, compatibilidad con HDR y un excelente rendimiento para juegos (frecuencia de actualización de 120 Hz). Ideal para quienes buscan una buena relación calidad-precio sin sacrificar la calidad de imagen.</p>', 'es');
